// 自动生成，请勿手动编辑。源：偈颂白话解.docx（extract_trans.py）。
window.TRANS = {"序-1": {"jie": "自利德：只有佛世尊断除了一切的不染污无知和染污无知，智德和断德都圆满\n他利德：拔济众生，超脱生死的系缚，具足恩德\n稽首接足，敬礼具有上述这样功德的、能宣说如理正教的世尊\n我将要宣说对法藏论", "ke": "归敬序 · 明佛三德"}, "序-2": {"jie": "无漏慧以及与其同时生起来的心王及心所法，名为胜义对法\n及能得无漏胜义对法的世俗对法：诸慧（生得慧、闻慧、思慧、修慧）和诸论（如《发智》、六足之类的这些论）\n本论能摄持《发智》《六足》等论的胜义；又依《发智》《六足》等论，由之引生\n所以立此论名，为“对法藏”论", "ke": "出对法体 · 明胜义对法"}, "序-3": {"jie": "若离开能简择诸法的智慧——无漏慧，定无余法能为灭诸烦恼之胜方便\n若烦恼不灭，则其力能使有情漂荡于三有之生死海中\n所以传说是佛所说的对法", "ke": "明说意说人 · 明说论意"}, "界-1": {"jie": "一切法可以分为有漏法和无漏法两种\n除道谛剩下的有为法都是有漏法\n于苦集谛烦恼随顺增长\n所以就叫有漏", "ke": "总明有漏无漏 · 总明"}, "界-2": {"jie": "无漏法包括道谛\n及三种无为法\n虚空无为、择灭无为、非择灭无为\n虚空无为以无碍为体", "ke": "别明无漏法 · 别明无漏"}, "界-3": {"jie": "择灭以离系为体。就是由择灭力，能离一切烦恼系缚。\n随系缚之多少，对治之择灭体亦有多少\n究竟阻止当来生法，令不生起，亦名缘缺不生\n非由择力令不生故，而得非择灭", "ke": "别明无漏法 · 释择灭"}, "界-4": {"jie": "有为法的体是色、受、想、行、识五蕴\n有为法有多异名：世路、言依、有离、有事，有果、有行、无常、世间等", "ke": "明有为异名 · 释有为名"}, "界-5": {"jie": "有漏法的异名：取蕴、有诤、苦、集、世间、见处、三有，非圣法、堕界、有染、有烦恼、有求、有取、有胜等", "ke": "明有漏异名 · 明有漏异名"}, "界-6": {"jie": "色蕴包含眼耳鼻舌身五根，\n色声香味触五境及无表色\n五根生的五识所依的是净色根\n叫眼等五根", "ke": "明色蕴 · 开章"}, "界-7": {"jie": "色法分为二种或二十种\n声有八种\n味有六种，香有四种\n触有十一种", "ke": "明色蕴 · 释五境"}, "界-8": {"jie": "1.明无表位能生起无表色的有四位：乱心位和不乱心位（散心位：善恶无记的三性心）、无心位和有心位（定心位：无想定灭尽定）\n2.明无表相无表色相似相续，并只有善恶两种性\n3.简诸得此无表色是由四大种所造\n根据婆沙师说，由以上三个条件名为无表色", "ke": "明色蕴 · 正明无表"}, "界-9": {"jie": "大种就是四个界：地界、水界、火界、风界。\n依照它们的次第，就是分别能成就持（任持）、摄（摄受）、熟（成熟）、长（增盛）四种作用。\n依照它们的次第来说，就是以坚、湿、暖、动为体性。地界是坚性，水界是湿性，火界是暖性，风界是动性。", "ke": "明色蕴 · 实四大种"}, "界-10": {"jie": "世俗的地是以显、形二色为体，就随顺世间俗情想法，安立此地界名。\n水、火二界也是随顺世俗想法，而于显、形二色上安立名称。\n风就是风界，因为世间人就是在「动」的体性上安立风名的缘故。", "ke": "明色蕴 · 假四大种"}, "界-11": {"jie": "此前所说十一种色蕴中，毘婆沙师允许就五根、五境而立为十处、十界。\n受蕴是以能领纳为它的体性，是随顺触因而生起的\n想蕴是以能取像为它的体性", "ke": "明色蕴 · 正立处界"}, "界-12": {"jie": "五蕴中除去前面的色、受、想蕴，及最后面的识蕴，其余的一切意志行为造作，就叫作行蕴。\n受、想、行蕴，以及无表色和三种无为法──虚空、择灭、非择灭无为，如此七法在处门中立为法处，在界门中立为法界。", "ke": "明受等三蕴 · 明受等三蕴"}, "界-13": {"jie": "每个识（眼耳等识）能各自了别它所缘取的每一个境界（色声等境），于自境处总取境相，所以叫识蕴。\n这个识蕴在十二处中，就是意处\n十八界里边就是七个心界\n就此六识界转谢过去后而变成为意界（即意根）。", "ke": "明识蕴 · 明识蕴"}, "界-14": {"jie": "即此六识身，中间毫无间断，于灭时，能为后识所依而生起后识，所以叫作意界。\n意界是第六意识依处。如此所依根、能依识、所缘境的界，应知各有六界，合成十八界。", "ke": "明识蕴 · 别立意难"}, "界-15": {"jie": "由五蕴中之一色蕴，十二处中之一意处，十八界中之一法界，就能总摄一切法。\n诸法唯能摄受与自己同性者，而不能摄受异于自己之他性。因为诸法与其它法之体性永远相离之故。", "ke": "明总摄 · 明总摄"}, "界-16": {"jie": "因左、右眼二处，同是眼根自体，同用色为境，同为眼识所依。由于如此，所以眼根虽有左、右二处，然而却只合为一界。\n为了让这所依身的相貌端正庄严的缘故，所以界体虽然只一个，但却分左、右两处而生。", "ke": "显数开合 · 明数合"}, "界-17": {"jie": "诸有为法（色、心、心所、不相应行等法）约其同类和合积聚，就是蕴的含义。心、心所法生长门之义，就是处的含义，就是说此能生长心、心所法，所以名为处，是能生长这心、心所法作用的意思。法种族之义，就是界的名义。\n众生愚迷于境有三种，众生的根性也有三种，众生的爱乐也有三种，因教化的众生有三类，所以世尊为说蕴、处、界等三科。", "ke": "释三法名 · 释三法名"}, "界-18": {"jie": "受想要特别地安立为蕴的原因有三，诤根因，即贪著诸欲及执著诸妄见；生死因，即贪著受，起颠倒想；次第因，即在五蕴里边，色、受、想 、行、识，这个次第是一定的", "ke": "释教起因 · 正明蕴废立"}, "界-19": {"jie": "三无为法不可说在色等蕴中，与色等义不相应故。", "ke": "释教起因 · 明蕴不摄无为"}, "界-20": {"jie": "在六根当中，眼等前五根只能缘取现前的外境，所以五根次第置前先说。\n这前五境中，前四境（色、声、香、味）唯是大种所造色，所以置前先说。\n眼、耳、鼻、舌前四根，这四根缘境时，因有远（距离）、快（速度）、明（了解、明白）的差别作用，所以置于前面先说。\n或者就在此身中随各根所依处（生长地方）上下的不同差别，而解说六根的次第。", "ke": "释教起因 · 处界次第"}, "界-21": {"jie": "为了令人了知色等五境及眼等五根各自有种种差别的缘故，所以于色蕴中就其根、境差别之相建立为十处，而不总为一色处。又诸色法中，色处最殊胜，所以用通名立为己名。又一切世间人，也只在这色处共同称说为色，而不是于眼等其它九处。\n又为了与其它十一处有所差别，所以特立一法处的名称，而不是于一切十一处立名，应知就如同色处立名的说法一样。", "ke": "明名废立 · 明名废立"}, "界-22": {"jie": "佛陀所说法有八万四千，有论师说佛陀教化众生是以言语声音为主体，他们说这些以言语声音为主体的法蕴，都是色蕴所摄。有论师说佛陀教化众生是以名（由文而成，具有意义的各种词类）、句（将名联络而诠释一种意义的语句）、文（指字之音韵）等为主体，他们说这些以名、句、文等为主体的法蕴，都是由行蕴所摄。", "ke": "摄法蕴 · 摄法蕴"}, "界-23": {"jie": "有论师说，佛说八万法蕴，每一法蕴中用来诠释的偈颂数量都与《法蕴足论》相等\n有论师说，法蕴的数量随著所诠释五蕴等每一义门的不同，而有八万。\n由于佛陀所教化的众生有贪、瞋等八万烦恼行类，为个别对治这八万烦恼行类，所以世尊便宣说这八万法蕴", "ke": "明法蕴量 · 明法蕴量"}, "界-24": {"jie": "佛于其它契经中所说的一切蕴、处、界诸法，各自随它所相应的，就应分别摄在前面所说的三科之中。\n如本论中所说蕴、处、界等诸法，应该要审慎观察那每一法的各别自相。", "ke": "类摄余蕴 · 类摄余蕴"}, "界-25": {"jie": "所有一切门、窗及口、鼻等内外的窍隙，就叫作空界。\n有部传说，窍隙就是明暗，不是离开明暗而有窍隙可得\n一切的有漏识，就叫作识界，是有情流转生死所依靠的", "ke": "别明六界 · 别明六界"}, "界-26": {"jie": "十八界中，色界是有见，因为有眼根能观照它。【注】十八界中，可以称之为有见的，只有六境界中的色境一界\n被色蕴所摄的十界（五根、五境）是有对，因为它们由极微所成，互相障碍。【注】十八界中，唯五根五境的十（有）色界是有对碍的\n在这里所说的十有对（五根、五境）中，除了色与声二界（通三性），\n是无记性，也就是这五色根，还有香、味、触三境，不可记说为善、不善性，所以叫作无记。【注，与上一句合并】于此十色界中，除去色声二界，余五根及香味触的八界是无记性。其余的七心界、法界、色界、声界的十界通三性", "ke": "诸门分别 · 有见无见门"}, "界-27": {"jie": "欲界所系属的具足十八界，\n色界所系属的只有十四种，\n就是除去了香、味二境及鼻、舌二识。【注，与上一句合并】色界所系属的只有十四种，就是除去了香、味二境及鼻、舌二识。\n无色界的系属，只有最后的三界—意界、法界及意识界。", "ke": "诸门分别 · 三界分别门"}, "界-28": {"jie": "意界及意识界为道谛所摄的部分，就名为无漏，其余就叫有漏。法界中如果是被道谛及三种无为（择灭、非择灭、虚空）所摄的部分，就名为无漏，其余就叫有漏。【注】意、法、意识的后三界，遍通有漏无漏\n剩下的十五界，就只称为有漏。\n眼、耳、鼻、舌、身五个识总是有寻有伺的，就是它要么不生，生的时候，决定有寻、伺两个心所跟它相应。【注】眼耳鼻舌身的五识界，与寻伺二心所，是俱生俱灭的\n后边三界——意界、意识界及相应的法界（除却寻、伺的其余四十四个心所）通三品：有寻有伺品、无寻唯伺品、无寻无伺品。“余无”，除了五识跟后三之外，剩余的十个色界（眼、耳、鼻、舌、身、色、声、香、味、触）只是无寻无伺，因为它们是物质，跟寻伺当然不相应。", "ke": "诸门分别 · 有漏无漏分别门"}, "界-29": {"jie": "说五识身（眼耳鼻舌身识）没有分别。\n是由于五识身虽有自性分别，却无计度分别和随念分别。自性分别分别的力量很弱，计度和分随念分别的分别力强，五识没有这两个强有力的分别，所以就叫它没有分别。\n依照次第说，意地（意识）散慧，是以诸念为体，散就是指它不是定，以第六意识相应的散慧计度，就叫计度分别。计度分别的体是意地的散慧，散就是不在定中。第六意识相应的，散的——没有入定的，那个慧心所，叫做计度分别。\n如果是以第六意识相应的定、散诸念为体，就叫作随念分别。第六意识相应的各式各样的念头——念心所，叫随念分别。意地里边，第六意识相应的念，念心所，这个念心所不限于散心的，定中也可以。", "ke": "诸门分别 · 有寻有伺门"}, "界-30": {"jie": "有所缘︰为心王、心所之异称，以心王、心所皆有所缘之境，故称有所缘。眼、耳、鼻、舌、身、意识，这个六识界，再加上意界，以及“法界半”——法界里边的一半，指的是相应心所法。这是些有所缘的。\n十八界把七个半除掉之后，还余下十个半，那就是没有所缘的。\n有执受之「受」，意谓有根身能产生苦、乐等之感觉、感受。反之，则称无执受、非执受。“前八界”就是“余无”那个八界——七个半界（七心界+法界里的一半），再加上一个“声”。这八界都是无执受的。\n十八界里边除了这九个界，“余”下来的九个界（五根与色、香、味、触四境）通“二”，通有执受、无执受。众生之五根与色、香、味、触四境，合之为九界，共为心与心所法所执持，且亦为心与心所法之依处，故称为有执受。", "ke": "诸门分别 · 有所缘无所缘门"}, "界-31": {"jie": "触界通于大种及所造二种。大种有四种，就是坚性、湿性、暖性、动性等；所造有七种，就是滑性、涩性、重性、轻性及冷、饥、渴等，因为这些都是依四大种而生，所以称作所造。\n其余九种色界，就是眼等五根及色、声、香、味等四境，全部都只是所造。\n以及法界一分，即无表业色，也是大种所造\n十八界中，五根、五境十有色界皆是可积集，因为都是由极微集聚所成的缘故。", "ke": "诸门分别 · 大种所造门"}, "界-32": {"jie": "色、香、味、触等身外四界，积集成刀斧、树薪等，这就分别称为能斫（刀斧）和所斫（树薪）。\n就如能斫、所斫，其体就只能是色、香、味、触外四界；所烧、能称，其体也是如此，就是说只有外四界叫作所烧、能称。\n能烧、所称有不同的诤论，有的论师说，能烧、所称之体也如同前文所说一样，只有外四界。又有论师说，只有火界可叫作能烧，而所称也只有触界中的一分重性。", "ke": "诸门分别 · 能斫所斫门能烧所烧门能称所称门"}, "界-33": {"jie": "眼、耳、鼻、舌、身等五界，这内五界都具有异熟生性和所长养性\n声界具有等流性和所长养性，但无异熟生性。\n七心界和法界，这八界都具有等流性和异熟生性。", "ke": "诸门分别 · 五类分别门"}, "界-34": {"jie": "色、香、味、触四界都通此三性──有异熟生性，有所长养性，有等流性。只有法界独称为有实。\n独得，就是说或有眼根界先前并未成就，现在得成就了，但并非得眼识。俱得，就是说或有眼根界、眼识界，这二界先前并未成就，现在都俱得成就了。非，就是说眼根、眼识俱未得。等，是说如有成就眼界，是否也成就眼识等问题。这应作四句来回答。", "ke": "诸门分别 · 五类分别门"}, "界-35": {"jie": "六根和六识，这十二界名为内界；外界就是其余的色等六境。凡是我（心识）所依处（六根）就叫作内；其余色等六境就叫作外。\n法界只有同分，其余十七界都具有同分和彼同分。\n就是依能行作自业，或不能行作自业而定。（根、境、识）如能各自行作自业，就叫作同分；不能各自行作自业，就叫作彼同分。", "ke": "诸门分别 · 内外门"}, "界-36": {"jie": "十色界及五识界这十五界惟独属于修道所断。意界、法界及意识界这后三界各通于见断、修断、非所断三种。\n不染法（有漏善、无覆无记）、非六生（非由第六意根所生的五识）、色法（有漏染、不染色），这些法必定非见道所断。", "ke": "诸门分别 · 三断门"}, "界-37": {"jie": "十八界中眼界全是见；法界一分中有八种是见；其余十六界全部及法界中其余部分，都不是见。八种见就是身见、边见、邪见、见取见、戒禁取见等五染污见，以及世间正见、有学正见、无学正见\n与五识俱生的慧不能决度的缘故，所以并不是见。", "ke": "诸门分别 · 是见非见门"}, "界-38": {"jie": "正做取色作用的同分眼与相应识合位时能见，而非其余一切时之眼都能见\n不是眼根所依的识能见\n传说因为眼不能观见被遮障的色境，所以现在所见被墙壁等所遮障诸色境，就不能观见了。", "ke": "诸门分别 · 是见非见门"}, "界-39": {"jie": "阿毘达磨诸大论师都说（有时一眼见色境），或者有时是由二眼同时看见色境。因为张开二眼时，见色分明；\n眼、耳、意这三个根，取的境不碰到【待重新白话】", "ke": "诸门分别 · 是见非见门"}, "界-40": {"jie": "唯取至境的鼻、舌、身等三根，应知都只能摄取等量的外境。\n意识唯依由六识身无间灭已的意根。\n眼等五识所依不仅是过去意根，也依现在世眼等五根。", "ke": "诸门分别 · 是见非见门"}, "界-41": {"jie": "眼识依眼根的原因，因为眼根变了，眼识也受影响，所以依眼根来立名；色变了，眼识不受影响。\n偈颂中「彼」字，就是指前面所说眼等六根名为所依，因为根是所依处，所以就随根而说识。「及不共」，是说眼根惟自身眼识所依；至于色境不但可为自身眼识所取，也可被他身眼识及自、他身意识所取，乃至身触应知也是如此。\n所以就随根而说识。", "ke": "诸门分别 · 是见非见门"}, "界-42": {"jie": "眼根相对于身生地来说，或相等的同在一地，或处于身生地的上面之地，但一定不会居于下面之地；\n色境、眼识相对于眼根来说，或相等的同在一地，或居于眼根生地的下面之地，一定不会居于上面之地\n境相对于眼识来说，通于相等的同在一地，或差别的在上面之地、在下面之地；\n色境、眼识相对于身体，其情况就如色境相对于眼识一样。", "ke": "诸门分别 · 是见非见门"}, "界-43": {"jie": "耳界，应知情况就如眼界一样，就是说耳根不会下于身生地；声境、耳识不会居于耳根的上界；声境相对于耳识，可通于一切（即或与耳识同地，或居上、下地）；\n鼻、舌、身三根，它们的根、境、识、身四法相望，都是住于自身生地。\n身识相对于触境和身根来说，或住于自身生地，或住于自身下地。\n应知意界的根、境、识、身四法相望，住处是不确定的。", "ke": "诸门分别 · 是见非见门"}, "界-44": {"jie": "色等五界，各个在六识中，分别被二识（眼等五识之一及意识）所识取。\n十八界中，没有一界全都是常住的，只有法界中一分无为法是常住的。\n色等五界，以及法界的一部分，都是体性而非根性。\n内十二界，是指眼等五根，就如自己名称而自相摄入，而意根是通被七心界所摄。最后三无漏根一分根体（意根），是被意界、意识界所摄入。女根、男根即是身根界一分所摄。", "ke": "诸门分别 · 几识所识门"}, "根-1": {"jie": "有部传说，眼耳鼻舌身五根，有四个增上作用：庄严身、导养身、生识等和不共事。\n女男命意四根各有两个增上作用。女男根有两个作用：有情异、分别异；命根有两个作用：能续过去众同分，能持现在众同分；“意根也有二个作用：能续后有，自在随行。\n五受根（苦乐忧喜舍）对染污的事情有增上作用，“信等八根（信勤念定慧、三无漏根）对清净的事情有增上作用。", "ke": "明二十二根：释根义"}, "根-2": {"jie": "眼等五根于能了别各别境识有增上用，第六意根于能了别一切境识有增上用。故眼等六各立为根\n从身根立女男根，女、男性别有增上作用", "ke": "叙异部"}, "根-3": {"jie": "命根，于同一个众同分住有增上作用；五受根于染污法有增上作用；信等五根，于清净法有增上作用。", "ke": "叙异部"}, "根-4": {"jie": "三个无漏根，从前到后，渐次有增上作用。未知当知根为它后头的已知根做增上作用，已知根对具知根有增上作用，具知根对涅槃有增上作用。", "ke": "叙异部"}, "根-5": {"jie": "眼等六根是心的所依，女男根形成有情相貌的差别\n有情要维持这一期生命，是靠命根；六根接触外境时生起五种受，产生杂染作用，立五受根。\n六根能为无漏净法作资粮，是由信等五根的增上作用；六根能够转成清净的，就靠三无漏根。\n由以上的标准立二十二根。", "ke": "明根废立"}, "根-6": {"jie": "眼、耳、鼻、舌、身、意六根，可作为有情流转生死的所依。\n识流转要生的时候，“由女男根；流转一期生死要住一下，就是命根；流转生死当中，有各种感觉、受用，是五受根；\n以流转的所依、流转的生、流转的住、流转的受用，这四个意思来安前面十四个根。\n还灭也是前面四个义，所依、能生、能住、还有受用对应而立的后八根。（还灭所依”是“信等五根，还灭生就是见道开始，已知根令涅槃得；还灭的受用，就是具知根受用现法乐住。）", "ke": "明根废立"}, "根-7": {"jie": "身上的不舒服叫苦\n身上的舒服叫乐\n在第三禅里边，心的舒服、那个好的受也叫乐\n除了三禅之外，心中的舒服，祗能叫喜，不能叫乐", "ke": "明根体"}, "根-8": {"jie": "心中的不舒服叫忧，不能叫苦\n身心的不苦不乐，都叫舍受，无区别\n见道时，依九个根（意、喜、乐、舍、信、勤、念、定、慧）立未知当知；修道时，依九个根立已知根；无学道时，也依这九个根，立具知根。", "ke": "明根体"}, "根-9": {"jie": "未知当知、已知、具知，三个根决定是无漏的，不通有漏。\n七色根（眼、耳、鼻、舌、身、女、男根）、命根、忧根、苦根共十个，只是有漏，不通无漏。\n“意、“喜、“乐、“舍，“加上信、勤、念、定、慧，共九个根，有的时候通有漏，有的时候是无漏。", "ke": "有漏无漏门"}, "根-10": {"jie": "命根决定是异熟果，它一生就是业所感的\n忧根和后面八个根（信、勤、念、定、慧及三无漏根），决定不是异熟。\n七色根（眼、耳、鼻、舌、身、女、男根）、意根，还有四受根（苦、乐、喜、舍）都通异熟、非异熟。", "ke": "是异熟非异熟门"}, "根-11": {"jie": "“忧定是要感异熟果的\n七色根（眼、耳、鼻、舌、身、男、女）及命根，是无记的，不感异熟果；后三就是三无漏根，因是无漏法，不感异熟果。\n“意根，苦、乐、喜、舍根，信等五根，共十个，有时候感异熟果，有时候不感异熟果。", "ke": "是异熟非异熟门"}, "根-12": {"jie": "三无漏根及信勤念定慧五善根，只是善性的。\n忧非无记，要么是善的，要么是不善的。\n意苦乐喜舍，共五个通三，善恶无记都有。\n七色根是无记的；命根，不相应行，也是无记的。", "ke": "三性门"}, "根-13": {"jie": "欲界、色界、无色界三个层次，挨著次第来分，欲界要除后三无漏根（欲界19根）\n色界，除三个无漏根，还要除女男根，再除忧苦根（色界15根）\n无色界，再除剩下的眼耳鼻舌身等色根，及喜乐根。（无色界8根：命意舍、信等五根）", "ke": "界系门"}, "根-14": {"jie": "意及喜乐舍三受，通三种断（见所断、修所断、非所断）\n忧是见所断、修所断。\n七色（眼、耳、鼻、舌、身，女、男根）、命、苦根，唯修所断。", "ke": "三断门"}, "根-15": {"jie": "欲界胎生、卵生、湿生的有情开始受生的时候有两个异熟根（命根、意根）\n欲界化生的有情开始受生的时候异熟根有六个（眼耳鼻舌身命）或七个（眼耳鼻舌身命，再加上男女中的一根）或八个（眼耳鼻舌身命，再加上男女二根）三种情况\n色界的有情开始受生的时候有六个异熟根，无色界的有情开始受生的时候只有命根。", "ke": "受生得异熟门"}, "根-16": {"jie": "有情在正死的时候，灭掉诸根的情况\n无色界是三个根（命意舍），色界是八个根（命意舍眼耳鼻舌身）\n欲界顿死的有情，灭根的情况是十个（眼耳鼻舌身女男命意舍），或八个（眼耳鼻舌身命意舍），或九个（眼耳鼻舌身命意舍，再加上女根或男根）；欲界慢慢死的有情灭掉的是四个根。如果是善心死的，每一种还要加上信进念定慧五个根。", "ke": "约死位灭根多少门"}, "根-17": {"jie": "初果（意根、舍根、信等五根、未知当知根、已知根）和四果（意根、舍根、信等五根、已知根、具知根）需要由九根证得\n一来果和不还果由七根，或八根，或九根证得\n有的地方说，阿罗汉果，有十一根（意、喜、乐、舍、信等五根、已知根、俱知根）证得。\n依一个有情，它可能有这个情况，有十一个根来得；但并非每一个有情都是十一根得阿罗汉。", "ke": "得果用根多少门"}, "根-18": {"jie": "假使成就命、意、舍三根中的任意一根，命、意、舍三个都会成就\n假使成就乐根或身根，一定成就四根（命意舍，再加上乐根或身根）", "ke": "成就诸根定量门"}, "根-19": {"jie": "假使成就眼、耳、鼻、舌等根及喜根中的任意一根，必定成就五根（命意舍身，再加上眼耳鼻舌中的任一根）\n假使成就苦根，至少有七根（身命意喜乐舍苦）成就", "ke": "成就诸根定量门"}, "根-20": {"jie": "假使成就女根、男根、忧根或者信等五根中的任意一根，决定有八个根同时成就\n假使成就已知根或俱知根，至少有十一根（命意喜乐舍、信等五根，再加上已知根或俱知根中的任一个）同时成就\n假使成就未知当知根，至少有十三根（身命意喜乐舍苦、信等五根，及未知当知根）同时成就", "ke": "成就诸根定量门"}, "根-21": {"jie": "成就根最少的情况有两类人：一类是没有善根的人，他成就的是五受根及命根、身根、意根；另一类是投生到无色界的凡夫，他成就的是信等五根及命根、意根、舍根", "ke": "成根极少门"}, "根-22": {"jie": "一个有情最多成就十九个根\n二形人可以成就十九个根（命意舍眼耳鼻舌身苦乐喜忧男女根，及信等五根），因为他没有三无漏根\n未离欲的（初果、二果及不还向）圣者也可以成就十九个根，因为三个无漏根他不可能同时具足，只能有一个，并且其女男根只能有一个。", "ke": "成根极多门"}, "根-23": {"jie": "欲界的一个微聚，如果没有声音和身根的话，至少有地水火风色香味触八事（无情）\n假使这是有情身上的微聚，那么加上身根就成为九事（地水火风色香味触及身根）\n假使还有眼睛，或者耳朵、鼻子的话，那就成为十事（地水火风色香味触、身根，再加上眼耳鼻中的任一事）", "ke": "明色法俱生"}, "根-24": {"jie": "心王和心所必定同时生起\n一切有为法跟生、住、异、灭四相也决定是同时生起的，有的时候，还要加一个得\n心所法有五种\n分别是大地法、大善地法、大不善地法、大烦恼地法和小烦恼地法", "ke": "明四品同起"}, "根-25": {"jie": "受、想、思、触、欲、慧、念、作意、胜解、三摩地这十个大地法遍于一切心", "ke": "大地法"}, "根-26": {"jie": "信、不放逸、轻安、惭、愧、无贪、无嗔、不害、精进这十个大善地法遍于一切善心", "ke": "明大善地法"}, "根-27": {"jie": "痴、放逸、懈怠、不信、昏沉、掉举这六个大烦恼地法，其自性只是染污性的，而且徧于一切染污心", "ke": "明大烦恼地法"}, "根-28": {"jie": "忿覆悭嫉恼", "ke": "明大烦恼地法"}, "根-29": {"jie": "欲界的心决定有寻伺\n欲界的善心品包括二十二个心所法，有恶作心的时候，还要再加上一个善的恶作", "ke": "明欲界俱生"}, "根-30": {"jie": "不善品里边与不共无明相应\n以及与不善的见相应的心，有二十个心所一起生。\n四烦恼（贪嗔疑慢）或十小烦恼地法随起一个的时候，有二十一个心所俱起\n不善心里边如果有个恶作心的话，就是二十一个心所俱起", "ke": "明欲界俱生"}, "根-31": {"jie": "欲界有覆无记心升起，决定有十八个心所同时俱生，\n欲界无覆无记的心起，有部承许有十二个心所俱生\n睡眠通三性的\n若有睡眠的话，随哪一品心就加一个心所。", "ke": "明欲界俱生"}, "根-32": {"jie": "初静虑要除掉十个不善心所（忿覆悭嫉恼害恨、无惭无愧、嗔）\n再除一个恶作，还要除一个睡眠，\n中间定的时候，比初禅里边再除一个寻。\n二禅以上的，除了前面所除之外，还要除伺、谄、诳。", "ke": "明上界俱生"}, "根-33": {"jie": "对那些有功德的人不尊重，不去恭敬他，谓无惭\n对于恶法能招可怕的果报，不知道生畏惧心，不知因果，谓无愧\n爱跟敬，体性是信心所与惭心所，\n缘补特伽罗的爱、敬，只欲界、色界有。", "ke": "明相似殊"}, "根-34": {"jie": "感到自己比人家胜，把自己抬高，就是慢的行相。\n把心抬得高，感到自己有些地方很殊胜，抬高自己，不顾念他人", "ke": "明相似殊"}, "根-35": {"jie": "心、意、识的体都是心王。\n心王、心所都是要有所依的根才能够生起\n心王心所都需要缘境才能够生起，心王、心所的行相是相等的\n心王心所相应的条件有五个：所依，所缘，行相，时，事", "ke": "明众名别"}, "根-36": {"jie": "一得，二非得，三同分，\n四无想果，五无想定，六灭尽定，七命根\n八生，九住，十异，十一灭，十二名身，十三句身，十四文身", "ke": "明不相应行"}, "根-37": {"jie": "得的自性有两个：获、成就\n非得的自性有两个：不获、不成就\n得和非得只有\n在有情自身身心相续与择灭、非择灭上", "ke": "明得非得自性"}, "根-38": {"jie": "过去、现在、未来每一世的法都各有三种得\n善法，不善的法，无记的法，所得的得也是善、不善、无记\n有漏法在哪一界，它的得也在哪一界\n择灭、非择灭三界都有，三界系的得都有，又有一种无漏得共四种", "ke": "明差别"}, "根-39": {"jie": "有学法的得是有学得、无学法的得是无学得、非学非无学法的得通三种\n无漏法上能得得，通二种：一种是修所断，一种是非所断。\n无覆无记的法和得是同时生起的（法俱得）\n从得俱起的角度来说，要除去天眼通、天耳通两个通果心", "ke": "明差别"}, "根-40": {"jie": "初禅的身语二业是有覆无记的色法，亦是法俱得\n欲界的色法没有法前得，只有法俱得、法后得\n非得体性是无覆无记\n过去世和未来世各有三世非得", "ke": "随难别解"}, "根-41": {"jie": "欲、色、无色界和无为法，他们的非得，通三界，没有无漏的，\n有部承许没有得到无漏的圣法\n就是凡夫\n非得的舍有两种：一种得到法；另外一种是更换地方。", "ke": "明非得差别"}, "根-42": {"jie": "有情相等的法就叫同分\n无想的异熟果就在无想天里面\n有部认为有一个叫无想的实法，可以把心王心所暂时灭掉\n修成功无想定，所感得的异熟果报，是在广果天", "ke": "明众同分"}, "根-43": {"jie": "无想定跟无想天一样，也是心心所法灭\n依第四静虑修无想定，目的是求解脱\n无想定的体性是善的，第二生一定投生到无想天\n无想定不是圣者所修，初念法俱得在现在世", "ke": "明无想定"}, "根-44": {"jie": "灭尽定也是把心心所灭掉(灭受想)，和无想定的作用一样\n修灭尽定目的暂时止息，要依靠非想非非想天的定来修\n灭尽定是善性的，受报时间可以是顺生受、顺后受和不定受三种情况\n需要圣者修很大的加行才能得到这个灭尽定", "ke": "明灭尽定"}, "根-45": {"jie": "佛得灭尽定和前边说的圣者不一样，不是加行得，是离染得\n因为佛陀三十四念成佛，三十四念中不能夹杂其他东西\n无想定、灭尽定，要依靠欲界或者色界的人才能起这两个定\n决定是在人中最初得到灭尽定", "ke": "明灭尽定"}, "根-46": {"jie": "命根的体，就是寿\n四相，就是一切有为法生住异灭的特性", "ke": "明命根"}, "根-47": {"jie": "四相，有生生、住住、异异、灭灭等四小相\n生、住、异、灭四种本相，分别对八个法有功能；四个随相，各自祗对一个法有功能。\n生，能生一切法（所生的法）\n但离不开因缘和合的作用", "ke": "明随相"}, "根-48": {"jie": "名身、句身、文身：\n名就是想，句就是章，文就是字，身就是总说（聚集的意思）。\n名句文身是欲界、色界有情摄\n名句文身是“等流性”“无记性”的", "ke": "明名身等"}, "根-49": {"jie": "同分跟名句文身一样\n同分除了欲界、色界，在无色界也是有的；除了等流、无记性，还有异熟性。\n“得”“四相”通三类：刹那性、等流性、异熟性。\n“非得”“二定”只有等流性", "ke": "明同分等"}, "根-50": {"jie": "有部承许六因包括：能作因、俱有因、同类因、相应因、遍行因、异熟因", "ke": "明六因"}, "根-51": {"jie": "除了自己之外，其它所有的一切法，都是它的能作因\n互为因果的，叫俱有因\n俱有因的体有三类：四大（地水火风）、能相和所相的法、心王和与心王同时生起的相应俱有法", "ke": "能作因"}, "根-52": {"jie": "心所、定共戒和道共戒，以及它们和心王上的四相（生住异灭）是心随转法。\n因为“时”“果”“善”的原因，所以叫心随转法", "ke": "明随转体"}, "根-53": {"jie": "同类因是因果相似的（三性）\n有漏法的同类因有两个限制：三界五部九地的限制，只能在自部自地下；因必须在果前，同类因只通过、现，不通未来（未来前后次第不定）。\n无漏道要修加行，果一定是和因相等或殊胜的。", "ke": "同类因"}, "根-54": {"jie": "加行生的有漏善法（闻思修所成的善法）也是等胜为果\n相应因决定是心王心所法（同一所依）。", "ke": "同类因"}, "根-55": {"jie": "遍行因（十一遍使）是因前果后\n可以为同地的一切染污法的因\n异熟因是善恶性的，且只是有漏的", "ke": "遍行因"}, "根-56": {"jie": "遍行跟同类因是“二世”，祗有过去、现在；异熟因、相应因、俱有因通三世\n果有两种，一种是有为的，一种是无为的——离系果\n无为法是能作因，但没有它所生的果；无为法是离系果，但没有能生它的因（是道所证）。", "ke": "三世分别"}, "根-57": {"jie": "异熟因生异熟果\n能作因生增上果\n同类因、遍行因，生等流果\n俱有因、相应因，生士用果", "ke": "对因配果"}, "根-58": {"jie": "异熟果是无记性的，是从有情身上善恶业产生的\n等流果的性质跟因（同类因、遍行因）的性质相似。\n离系果是用智慧把烦恼灭掉证得的", "ke": "别显果相"}, "根-59": {"jie": "假使用其他的一个力量产生的果，这个果就叫士用果\n在除去因之前的有为法\n剩余的有为法都可以是增上果（因前果后）", "ke": "别显果相"}, "根-60": {"jie": "除去能作因的五个因，取果唯在现在世。\n俱有因和相应因与果，也同样是在现在世。\n同类因和遍行因与果，通过去世与现在世。\n异熟因与果，唯在过去世。", "ke": "明因取与果"}, "根-61": {"jie": "染污法、异熟生法\n三所余法以及初无漏法，\n依次除去：染污法除去异熟因，异熟生法除去遍行因，三所余法除去异熟因和遍行因，\n初无漏法除去异熟因，遍行因和同类因，由另外的三个因生。", "ke": "明法从因生"}, "根-62": {"jie": "以上四类法从因所生，是针对心心所的相应法而言。\n色法及不相应的四类法从因所生，还要在此基础上除去相应因。\n经中说缘有四种\n因缘的体，是除去能作因之外的五个因。", "ke": "明法从因生"}, "根-63": {"jie": "等无间缘，要除去阿罗汉临入涅槃最后心心所，\n剩余的一切心心所，都是等无间缘。\n所缘缘，所缘的是一切法。\n所谓的能作因即是增上缘。", "ke": "明四缘体"}, "根-64": {"jie": "俱有因和相应因在正灭时（现在世）有与果的作用。\n同类因、遍行因和异熟因在正生时（未来世）有与果的作用。\n等无间缘于正生时、所缘缘于正灭时，\n而有与果的作用。", "ke": "明缘作用"}, "根-65": {"jie": "心、心所法由四个缘生\n灭尽定和无想定由三个缘生，除去所缘缘\n色法和不相应行法（除去二定），由因缘和所缘缘两个缘生\n世间诸法决不会从自在天等一因所起，因为现见诸法是由次第而起的", "ke": "总明诸法"}, "根-66": {"jie": "四大种望于四大种，为俱有因与同类因两个因。\n四大种望于所造色，为生、依、立、持、养的五个因（同属能作因）\n所造色望于所造色，为俱有因、同类因和异熟因三个因。\n所造色望于四大种，唯有异熟因一个因。", "ke": "随难别解"}, "根-67": {"jie": "欲界有四种心：\n善心、恶心、有覆无记心、无覆无记心。\n无色界各有三心，除去恶心。\n无漏的二心是有学心和无学心。", "ke": "列十二心"}, "根-68": {"jie": "欲界善心，无间生九心。\n欲界善心从八种心生，即欲界的四心、色界二心和无漏二心。\n欲界不善、有覆无记二种染心，从欲界四心、色界三心和无色界三心十心所生；能生欲界四心。\n欲界无覆无记心，从自界四心及色界善心五心所生；能生七心，即欲界四心、色界善心及有覆无记心、无色界有覆无记心。", "ke": "正辨相生"}, "根-69": {"jie": "色界善心无间生十一心，除无色界无覆无记心；\n从九心生,除欲界的二染污心及无色界的无覆无记心。\n色界的有覆无记心从八心生起，除去欲界的二种染心及学无学的二无漏心。\n能生六心，即色界的三心和欲界的善、不善、有覆无记的三心。", "ke": "正辨相生"}, "根-70": {"jie": "色界的无覆无记心，是从自界的善、有覆无记、无覆无记三心生\n能生起六心，自界善、有覆无记和无覆无记，欲界有覆无记和恶心，无色界的有覆无记心。\n无色界的善心无间生九心，即除去欲界善心、欲色二界各一无覆无记心。\n从自界的三心、色界的善心、学无学二心的六心所生。", "ke": "正辨相生"}, "根-71": {"jie": "无色界的有覆无记心无间生七心，即自界的三心，色界的善、有覆无记二心，欲界的恶、有覆无记二心；从七心生，即欲界、色界善和无覆无记，无色界三心。\n有学心，从三界善心及有学心四心所生，能生三界善心及学无学心的五心。\n无学心，从三界善心及学无学心五心所生，能生三界善心及无学心四心。", "ke": "正辨相生"}, "根-72": {"jie": "十二心变为二十心，\n就是：三界的善心\n分为加行善和生得善，\n欲界的无覆无记，分为四种：", "ke": "明二十心"}, "根-73": {"jie": "异熟生，威仪路，\n工巧处和通果心。\n色界的无覆无记，除去工巧处，\n其他的如上所说，总计二十心。", "ke": "明二十心"}, "根-74": {"jie": "三界的染污心现前时，\n欲界染污心得六种心（欲界善、恶、有覆三心，色界无色界有覆无记心，学心），色界染心同样得六心（色界的善、有覆、无覆的三心、欲界的无覆无记心、无色界的有覆无记心，学心），无色界染心得二种心（无色界的有覆无记心，学心）。\n色界善心得三心（色界的善心，欲界色界通果无记），有学心得四心（有学心、欲界色界的通果心、无色界的善心）。\n三界的各一无覆无记心、欲界及无色界的各一善心，再加一无学心，此六心正现在前的时侯，一一唯可自得。", "ke": "明得心多少"}, "世间-1": {"jie": "欲界五趣：地狱、傍生、鬼、人、天。六欲天：四天王众天、三十三天、夜摩天、睹史多天、乐变化天、他化自在天\n地狱、饿鬼、旁生、人类以及六欲天被称为欲界。其中地狱有八个，人类分四大部洲，这样欲界共有二十类。", "ke": "明三界"}, "世间-2": {"jie": "此欲界上，有十七处，名为色界。\n初、二、三静虑各三处，第四静虑有八处，总合有十七处。", "ke": "明三界"}, "世间-3": {"jie": "无色界没有处所的，无色界差别有四个，因为它的异熟生不同，说有四空处。\n虽没有色身，但有同分以及命根，即依此命根及同分，心心所法得以相续，", "ke": "明三界"}, "世间-4": {"jie": "在三界中，随其所应，说有五趣，各如自名所显，就是前面所说的地狱、傍生、鬼、人、天，是名五趣。\n三性分别，此五趣体，不通善染性，唯无覆无记，过去业所招，是异熟生无记，五趣唯是有情数摄，体非中有", "ke": "明五趣"}, "世间-5": {"jie": "七识住（识所欢喜住的地方）指：第一是身心都不一样；第二是身不一样但想一样；\n第三是身一样想不一样；第四是身想都一样；和无色界下三个（空无边、识无边、无所有），一共七个。", "ke": "明七识住"}, "世间-6": {"jie": "所以七识住就指这七种，这七个地方以外不是七识住，因为对识有损坏。\n以上七识住再加上有顶天和无想天的有情", "ke": "明七识住"}, "世间-7": {"jie": "这样就是九有情居，之外其它地方有情不乐住，所以不是有情居。\n四识住的地方我们要知道，它的体就是自地的四个蕴，色、受、想、行。", "ke": "明九有情居"}, "世间-8": {"jie": "于五蕴中，独有识蕴非是识住。四识住与七识住对比，都是有漏的；但各自的范围互通有无，需要用四料简来分析。\n在三界五趣中有此四生。即有情类中，有卵生、胎生、湿生、化生的四种。", "ke": "明四识住"}, "世间-9": {"jie": "人趣及傍生趣，各各具有四生。极苦的地狱有情、极乐的天趣有情。\n（接前一句）中有只有化生，饿鬼有胎生和化生二种。", "ke": "明四生"}, "世间-10": {"jie": "生有和死有中间的五蕴，叫中有。\n它该投生的地方还没有到，所以中有不叫生，叫起。", "ke": "正明中有"}, "世间-11": {"jie": "中有如榖等作物生长相续不断，因为死生也是相续法，所以死生是处无间（不会断的），即需要中有。\n镜像不是实有的法，像与法不相等所以譬喻不成立。", "ke": "正明中有"}, "世间-12": {"jie": "一个地方没有两个色法并存，质与像不是相续法，像是依托二缘生的。\n佛说有《健达缚经》，还有五不还（一中般、二生般、三行般、四无行般、五上流般）及《七善士经》。", "ke": "正明中有"}, "世间-13": {"jie": "中有与本有同一引业。由业同故，中有的形状跟未来本有的形状一样。\n死有之前，投生刹那以后，这个中间的一个阶段，就是叫本有。", "ke": "明中有形状"}, "世间-14": {"jie": "中有的同类和修得净天眼的人，可以看见中有身。中有能飞行自在，它是业报得来的业通。中有是五根具足的。", "ke": "明眼等九门"}, "世间-15": {"jie": "中有投生时，以颠倒心驰趣欲境。湿生对香气起染着，往彼处受生。化生对处所起染着，前往受生。\n投生到天上，中有的头朝上。投生人、傍生、饿鬼，头是横的（不朝上也不朝下）。投生地狱的头朝下。", "ke": "明眼等九门"}, "世间-16": {"jie": "中有入胎，一种是唯入胎时能正知，不知住胎、出胎；二是入胎和住胎能正知，不知出胎；三是入、住、出胎都能正知。\n第四种是入、住、出胎都不知道，卵生的中有，跟第四种一样，皆不知。", "ke": "明入胎门"}, "世间-17": {"jie": "前三种入胎依次是指轮王、独觉辟支佛、大觉佛。\n原因是：轮王仅福（业）胜；独觉仅智胜；大觉佛福智俱胜；其他众生，福智均劣，属于第四种情形。", "ke": "明入胎门"}, "世间-18": {"jie": "没有我只有五蕴，假立五蕴为我在流转；五蕴流转的根本是烦恼和业。\n因为有个中有身，他可以使得这一辈子到下一辈子连续起来，中间没有断掉，就如油灯之火焰那样，不断地在生灭，但仍可以有相续。", "ke": "遮外道难"}, "世间-19": {"jie": "根据它的引业，入胎之后，诸蕴次第增长，相续不断，是由烦恼和业力所牵引的。\n入胎出胎，出胎后再老死，老死后再投胎，一直旋环轮回，无始无终。", "ke": "遮外道难"}, "世间-20": {"jie": "如前所说的缘起，共有十二支，分前中后三际（前际、中际、后际）。\n前、后际各有二支；中际，如果圆满具足的情况（如无中夭），有八支。", "ke": "广明十二缘起"}, "世间-21": {"jie": "过去世起烦恼时的五蕴体，总称为无明。过去世造业的五蕴体，总称为行。\n识支是指正在结生的五蕴体。名色指结生刹那后到生出六根之前的五蕴体。", "ke": "总判支位"}, "世间-22": {"jie": "六处即从生出五根到根境识三和合前的五蕴体。\n从出生后到两三岁之前，根境识已经生起来了，这个阶段的五蕴体叫触。", "ke": "别显体性"}, "世间-23": {"jie": "为获得淫爱、妙资具等境界而遍驰求索阶段的五蕴体名取。", "ke": "别显体性"}, "世间-24": {"jie": "贪求过程中造作能感后有之业的五蕴体名有。\n后际结生刹那的五蕴体即生。后际从生到受的五蕴体名老死。", "ke": "别显体性"}, "世间-25": {"jie": "根据有部毗婆沙师的说法，世尊是从分位缘起来说十二缘起的。各支的体性实为五蕴，但依照此阶段突出的特征而立支名，如五蕴中无明强盛，故立无明支。\n世尊唯约有情说十二缘起，是为了遣除众生的三际愚惑。", "ke": "明本说意"}, "世间-26": {"jie": "三烦恼（无明、爱、取三支，烦恼为性），二业（行、有二支，以业为体）。七事亦名果者，除前五支，余识等七，名之为事，是烦恼业所依事故，如是七事（识、名色、六处、触、受，生、老死，），亦名为果。\n前际烦恼只有无明一支，相比中际烦恼有两支（爱、取），是略因；后际事只有两支（生、老死），相比中际五支（识、名色、六处、触、受），是略果。虽然前际略说因，后际略说果，但通过中际可以得知，前际因和后际果的内涵。", "ke": "遣他疑惑"}, "世间-27": {"jie": "从烦恼可以产生烦恼，也可以产生业，就是烦恼生烦恼，烦恼能生业。业又能产生事或果。\n事能生事，也能生惑。因此，缘起只要十二支就够了，不要多了，因为产生无明（即惑）的因，以及老死（即事）的果，在中际已经开显出来了。", "ke": "以略摄广"}, "世间-28": {"jie": "经里边提到缘起法和缘已生法。各支从因的角度来讲，叫缘起法；从果的角度来讲，叫缘已生法。\n明就是智慧，它针锋相对的那个法叫无明。无明和明，就像怨敌和亲友，虚妄和真实等之间的关系。", "ke": "会释经文"}, "世间-29": {"jie": "经中说有无明结、无明轭等，这也是说明无明有体。无明不是恶慧，因为慧有见的，而无明是没有见的。\n无明可以跟见相应的，故知无明也不可说为无见性的慧（否则，无明起来，则有一个慧跟一个见相应，如此一心中有两个慧心所，这是不允许的）。无明这个心所法，把智慧染污了，使它不清净，也说明无明不是慧（因为不能自己染自己）。", "ke": "明无明"}, "世间-30": {"jie": "所谓名者，是无色的四蕴（受、想、行、识）；眼识相应触等六个触，是根境识三者和合产生的。\n眼识相应触，乃至身识相应触五个又称为有对触；第六个意识相应触又称为增语触。", "ke": "明名色    H3 明触"}, "世间-31": {"jie": "无漏相应的触叫明触，染污相应的触叫无明触，有漏的善跟无记法相应的触，叫非明非无明触。\n跟那个贪相应的触叫爱触，跟瞋相应的触叫恚触。跟乐受相应的触叫顺乐受触；跟苦受相应的触，叫顺苦受的触，与舍受相应的触，叫顺不苦不乐受的触。", "ke": "明二触"}, "世间-32": {"jie": "从前面那六个触，可生六个受，就是眼触所生的受，耳触所生的受等，其中有五种受属于身受，剩下一种属于心受。\n由于意近行的差别，心受又分成十八种受。", "ke": "明受 I1 总明"}, "世间-33": {"jie": "有情在欲界，缘欲界有18种意近行；缘色界、无色界分别有12种、3种意近行。\n有情在初禅、二禅，缘欲界有12种意近行，缘色界、无色界分别有8种、2种意近行；", "ke": "义分别"}, "世间-34": {"jie": "有情在三禅、四禅，缘欲界有6种意近行，缘色界、无色界分别有4种、1种意近行；\n有情在空无边处近分，缘色界第四禅有4种意近行，缘无色界有1种意近行。", "ke": "系缘"}, "世间-35": {"jie": "有情在无色四根本定和后三定的近分定，只缘无色界，有1种意近行。\n十八种意近行，只能是有漏的，没有无漏。前面已经说了无明等四支，剩余支在前面的品里已经说了，或者在未来的品里将会说到。", "ke": "系缘"}, "世间-36": {"jie": "此中就是十二支里边的烦恼，如种子能生芽，如龙在池水恒不竭\n如草根未拔还会生起，如只断树茎留有树干还会新生。如糠包米在地下还能生芽，业有烦恼的话，还能感余生。", "ke": "略摄喻显"}, "世间-37": {"jie": "业有烦恼能招异熟，如同米有糠包着能生芽；业招果后不再招异熟，如草药结果就没有作用了，业于异熟果为近因，如花对于果为近因。\n诸异熟果成熟后不再招异熟果，如同熟食，一但做好便不可转成其它饮食。", "ke": "略摄喻显"}, "世间-38": {"jie": "在四有（生有、中有、死有、本有）里边，生有决定是染污的，不染污不会投生。\n因为生在这个地，决定是这个地的烦恼把你系住了。其余三有（本有、死有、生有）的心三种都有：染、善、无记。在三界之中，无色界祗有三个有：本有、死有和生有，没有中有。", "ke": "明四有"}, "世间-39": {"jie": "一切有情无非由食而住。食有四种：一段、二触、三思、四识。祗有欲界有段食，段食的体是有三个：香味触。\n色不是段食，因为它尚且不能够滋养眼根，对解脱也没有帮组。", "ke": "明有情住"}, "世间-40": {"jie": "触食、思食、识食，是有漏法，三界都有，段食祗有欲界有。\n中有有五个名字，意成、求生、食香、中有、起。", "ke": "明有情住"}, "世间-41": {"jie": "前面两个食，段食、触食，对我们这一辈子的身体（包括所依和能依）有好处。所依，就是我们的色根，能依就是我们的心、心所\n后边两个食，思食，识食于当有（下一辈子）有作用。依次（如次）为：思食能引起来（思造业），识食能够生起来（识种子现行生出来）。", "ke": "明有情住"}, "世间-42": {"jie": "断善根、续善根、离染得定、重新起烦恼（阿罗汉退果）、死和生六事\n（前面六事）都是意识的事情；死和生的时候，都是舍受相应。", "ke": "明有情没"}, "世间-43": {"jie": "不会在定心‘和无心定（灭尽定和无想定）下死生；入涅槃心只有二无记心，即异熟生和威仪路。", "ke": "明有情没"}, "世间-44": {"jie": "下指三恶趣；人指人中；天指天中；不生指得罗汉（与前两句连起来看）。水、火和风碰到身中末摩（死穴），人便死了。\n有情分成三类：正性定聚、邪性定聚和不定性聚。（见道）圣人属于第一类，造五无间罪的人属于第二类，剩下的属于第三类。", "ke": "明有情没"}, "世间-45": {"jie": "器世间的最底下一层是风轮。\n其量广无边，厚度为十六亿逾缮那。", "ke": "明器世间 B1 明所居器"}, "世间-46": {"jie": "风轮上面是水轮，深度有十一亿二万逾缮那。\n水轮最上面一层是金轮，厚度大约三亿二万逾缮那，剩下的八十万逾缮那仍是水，剩余部分形成了金轮。", "ke": "明三轮"}, "世间-47": {"jie": "水轮和金轮都一样宽广，直径是十二亿三千四百半逾缮那\n金轮和水轮的直径都是十二亿三千四百半逾缮那，其周围是直径的三倍。", "ke": "明三轮"}, "世间-48": {"jie": "金轮中间是妙高山，也叫须弥山，外面第二层是持双山。\n第三层是持轴山，第四层是竭地洛迦山。", "ke": "明九山"}, "世间-49": {"jie": "第五层是善见山，第六层是马耳山。", "ke": "明九山"}, "世间-50": {"jie": "尼民达罗山之外是四大洲，四大洲之外有大铁围山。\n前面七个山都是金子所成。妙高山则是有金、银、吠琉璃和颇胝迦宝构成。", "ke": "明九山"}, "世间-51": {"jie": "九座山没于水中的部分都有八万逾缮那，须弥山出水部分亦是八万逾缮那。\n其余八座山的出水高度依此减半，它们的厚度均与其各自高度等同。", "ke": "明九山"}, "世间-52": {"jie": "须弥山至持边山之间，有八个海，前七个是内海。\n最内的海面宽为八万逾善那，持双山四边各边的宽度为海面宽度的三倍（外围四边均为二十四万逾善那）。", "ke": "明九山"}, "世间-53": {"jie": "其余六个海面宽度依次减半，第八海是外海\n第八外海，是持边山到铁围山之间，其宽度为三十二万二千逾缮那。", "ke": "明八海"}, "世间-54": {"jie": "这其中四大洲的形状，南瞻部洲如古印度马车形状。\n南瞻部洲三边宽各两千逾善那，南边狭，只有三个半逾善那。", "ke": "明八海"}, "世间-55": {"jie": "东毗提诃洲形状如同半圆。\n东毗提诃洲三边与南赡部洲相同，两千逾善那，东边最小边为三百五十逾缮那。", "ke": "明四大洲"}, "世间-56": {"jie": "西瞿陀尼洲形状为圆形，毫无缺损。\n直径则为二千五百逾缮那，周长为七千五百逾缮那。", "ke": "明四大洲"}, "世间-57": {"jie": "北俱卢洲形状是四边相等的正方形，每边长都为二千逾缮那。\n复有八个中洲，位于四大洲侧边，每大洲各有二个中洲。", "ke": "明四大洲"}, "世间-58": {"jie": "此赡部洲，从中向北，三处各有三重黑山（共九重）。黑山北面有大雪山，大雪山北面有一座山，叫香醉山。此山有香，人嗅便醉。\n无热恼池，纵广正等，五十逾缮那。", "ke": "明黑山等"}, "世间-59": {"jie": "南赡部洲地下，二万个逾缮那那么深，下边就是无间地狱。\n七个地狱（捺落迦）在无间地狱上边。八个捺落迦中，每个地狱外四边各有四个（共十六个）游增地狱。所谓增，即在大地狱受苦之后，还要增上的受苦，再受苦。", "ke": "明地狱"}, "世间-60": {"jie": "四个游增地狱分别为：煻煨地狱，尸粪地狱，锋刃地狱，烈河地狱。\n十六个游增地狱在大地狱四面，每面各四个。八寒地狱，一、頞部陀；二、尼刺部陀；三、頞哳咤；四、臛臛婆；五、虎虎婆；六、嗢钵罗；七、钵特摩；八、摩诃钵特摩。", "ke": "明地狱"}, "世间-61": {"jie": "太阳和月亮在妙高山的一半位置依空而住。日月的大小，直径分别祗有五十一、五十逾缮那\n北俱卢洲处于半夜的时候，东胜神洲正好是太阳刚下去即黄昏的时候，南瞻部洲正处于太阳当午的时候，西牛货洲此时太阳刚出来", "ke": "明地狱"}, "世间-62": {"jie": "从雨季第二个月后半个月的第九日开始，晚上时间开始越来越长（对应白天的时间越来越短）；\n从寒季第四个月后半个月的第九日开始，晚上的时间开始越来越短（对应白天的时间越来越长）；", "ke": "明日月等"}, "世间-63": {"jie": "昼夜增时，每天增加一腊缚的时间（大约1.56分钟），减时亦然。太阳的轨道在南瞻部洲航行的时候，偏于南，那么就是夜增，偏于北，则昼增；\n月亮跟太阳在走，航行的时候，它靠近太阳哪一边，就发光了，太阳没有照到那一边就有个影子，这个影子把自己的半个月亮盖掉了，所以那个时候看不到了，不圆了。", "ke": "明日月等"}, "世间-64": {"jie": "妙高山从海平面往上分了四层，各层相距的距离都是十千、就是一万逾缮那。\n从山身旁出部分的宽度，最下层有十六千就是一万六。上边依次是八千，四千，二千逾缮那。", "ke": "明天器"}, "世间-65": {"jie": "坚手住在最低一层。第二层住的是持鬘 ，第三层是恒憍，第四层是四天王自己住。\n如次第住须弥山四个层级。其余七座金山里边，都有天人住，包括太阳、月亮也在里边。", "ke": "正明天器"}, "世间-66": {"jie": "妙高山的顶上，四边各八万逾缮那，是三十三天居的地方。\n山顶在东北，西北，西南，东南四个角有四个山峰，各有五百逾缮那那么高，那么宽。有叫金刚手的药叉神守护。", "ke": "明三十三天器"}, "世间-67": {"jie": "帝释天的首都中有一个善见宫殿，周围一共一万个逾缮那。\n他们的首都（金城）高一个半逾缮那，城内地触柔软，有如罗绵 。", "ke": "明三十三天器"}, "世间-68": {"jie": "善见城里边有个殊胜的宫殿（帝释天所住），周围是一千逾缮那 。\n城外四面有供戏乐的庄严林苑 ，分别叫众车苑、粗恶苑、杂林苑、喜林苑。", "ke": "明三十三天器"}, "世间-69": {"jie": "林苑四边有四妙地，地中间距苑各是两千逾缮那。\n在帝释天东北方有个圆生树，在西南角有一个善法堂。", "ke": "明三十三天器"}, "世间-70": {"jie": "忉利天以上的有色天，它的住处，依空而住。\n六个天人淫欲方式：四天王天和忉利天都是相交、夜摩天拥抱；都史多天执手；乐变化天相笑；他化自在天相视。", "ke": "明空居天"}, "世间-71": {"jie": "六欲天初生时的体量如人间五岁那么大的小孩，且圆满有衣在身。\n欲生有三种：谓人趣及下四天；乐变化天；他化自在天。乐生在三个静虑中，每个静虑里边三个天，共九处。", "ke": "明诸天初生"}, "世间-72": {"jie": "每个天离下面海有多远，它上面的天离它也一样远。\n若去上层天，要自己有神通，或者有神通的人把自己带上去，或上层天来接。", "ke": "明欲生乐生"}, "世间-73": {"jie": "一个四大洲，日，月，须弥山乃至欲界天，\n一直到梵天，以上叫一个小世界。一千个小世界，叫一小千世界。", "ke": "明下见上天"}, "世间-74": {"jie": "小千世界的一千倍，叫一个中千世界。\n中千世界的一千倍，叫大千世界。他们都是一同成住坏灭的。", "ke": "总辨大千"}, "世间-75": {"jie": "赡部洲，大部分人身长三肘半，少数人身长四肘。\n东胜身洲人身长八肘。西牛货洲人身长十六肘。北俱卢洲人身长三十二肘。", "ke": "明能居量"}, "世间-76": {"jie": "欲界六天，最下身量，为一俱卢舍的四分之一。如是后后，依次增四分之一，至第六天，为一个半俱卢舍。", "ke": "明身量"}, "世间-77": {"jie": "从少光天以上诸天，皆一倍一倍增。唯无云天，减三逾缮那\n北俱卢洲人，定寿千岁。西牛货洲人，寿五百岁。东胜身洲人，寿二百五十岁", "ke": "明身量"}, "世间-78": {"jie": "南赡部洲人，寿无定限。谓劫减位，寿量最短为十岁，而劫初时，寿无量，百千等数，不能计量。\n人间五十年，为四天王天一昼一夜", "ke": "明善趣寿量"}, "世间-79": {"jie": "以四天王天的昼夜，三十日为一月，十二月为一年，彼寿五百岁。上五欲天的寿量，依次倍增。\n色界天，没有白天黑夜，他的寿命以劫来算，数值跟他的身量一样的，", "ke": "明善趣寿量"}, "世间-80": {"jie": "无色界，最初的空无边处，二万大劫，后边的就是两万两万的增，增到最高的八万大劫，\n这个劫数也不一样，少光天的上边，劫是指一个大劫，少光天下边，劫是指半个大劫，这个单位有不同。", "ke": "明善趣寿量"}, "世间-81": {"jie": "四天王等六欲天的寿量，如其次第，分别为等活等六捺落迦一昼一夜，此六地狱的寿量依次跟对应的六欲天相同。\n四天王天，寿量五百岁，于等活地狱，为一昼一夜。乘此昼夜，成月及年，以如是年，彼等活地狱寿五百岁。", "ke": "明恶趣寿量"}, "世间-82": {"jie": "第七极热地狱，寿半中劫，无间地狱，寿一中劫（二十增减劫，为一中劫也)。\n傍生寿量多少，无定限，极长的寿量，亦一中劫。鬼以人间一月为一日，以此成月年，彼寿量五百年。", "ke": "明恶趣寿量"}, "世间-83": {"jie": "第一个寒冰地狱的寿量，比喻成这样：有一篅量的麻，\n一百年拿掉一颗，那把麻拿完，它的寿命还没有完，后面的地狱寿量是二十倍地增加。", "ke": "明恶趣寿量"}, "世间-84": {"jie": "诸处皆有中夭，除北俱卢洲，彼定千岁。", "ke": "明中夭不中夭"}, "世间-85": {"jie": "极微、微量、金尘、水尘、兔毛尘、羊毛尘、牛毛尘、游隙尘\n虮身上长的一个汗虫，虱子、麦子、指节，到指节为止，都是七倍七倍增，", "ke": "明三极少"}, "世间-86": {"jie": "二十四指，作横形排列起来，就为一肘。积四肘为一弓量。\n积五百弓为一俱卢舍，积八俱卢舍为一逾缮那。", "ke": "明二量"}, "世间-87": {"jie": "六十个怛刹那为一个蜡缚，一腊缚约一分三十六秒。三十个蜡缚为一个须臾，一须臾约四十八分钟。", "ke": "明刹那至年"}, "世间-88": {"jie": "三十个须臾是一昼夜，三十个昼夜又是一个月。\n十二个月是一年，一年中有六个月少一夜，少一天，那是小月。", "ke": "明刹那至年"}, "世间-89": {"jie": "劫有四种：一坏，二成，三中，四大。（坏劫中含有空劫，成劫中有住劫，所以不特别另说住劫和空劫。）\n言坏劫者，谓从地狱有情不复更生，至外器都尽。", "ke": "明劫量"}, "世间-90": {"jie": "成劫，指从虚空中起了运动的气体，至有情开始投生地狱。\n中间劫从南瞻部洲人寿无量岁开始一直减到十岁为止。", "ke": "明劫数"}, "世间-91": {"jie": "此后有十八个中间劫，每个中间劫寿量皆有增减：先从十岁增至八万，再从八万岁减至十岁。第二十中间劫唯增无减，谓从十岁，增至八万。\n这样二十个中间劫，总名为成已住劫。", "ke": "明劫数"}, "世间-92": {"jie": "世间成经二十个中间劫，成已住又经二十中间劫，合名成劫；世间坏经二十中间劫，坏已空又经二十中间劫，合名坏劫。各各皆成二十中间劫，所以说坏与空时皆等住劫。\n成、住、坏、空各二十中间劫总和起来，合八十中间劫为一大劫。大劫从十百千累积成不可统计的劫量，而成为三无数劫的。", "ke": "明劫数"}, "世间-93": {"jie": "佛出现，决定是减劫，从八万岁减到一百岁左右的时候，诸佛就出现于世间。\n独觉出现就不一定，增劫、减劫都可以出现。麟角独觉，一定要经百劫修菩提资粮。", "ke": "明劫中人"}, "世间-94": {"jie": "南瞻部洲人寿从无量岁，至八万岁，有轮王出。轮王有四种：金轮王、银轮王、铜轮王、铁轮王。\n铁轮王统治一洲界；铜轮王统治二洲界；银轮王统治三洲界；金轮王统治四洲界。轮王如佛，无二俱生，唯一出现。", "ke": "明佛独觉"}, "世间-95": {"jie": "金轮王是其他的国家自己来迎请他去统治他们的地方；银轮王他要去一下，他们才服；铜轮王他要自己给他们宣告一下自己的一些德政，然后他们才服；铁轮王要把部队带去，他们看到部队来了，就害怕了，就伏了。一切轮王，皆无伤害。", "ke": "明轮王出现"}, "世间-96": {"jie": "劫初时人，皆如色界，诸根无缺，形色端严，身带光明，腾空自在，饮食喜乐，长寿久住。后有地味渐生，后有一人贪其地味而食。", "ke": "明劫初有王"}, "世间-97": {"jie": "于是十恶业道就增盛起来，而人寿亦随之逐渐减少，直至人寿减到十岁定命时，世间有小三灾起。\n刀兵劫、疾疫劫、饥馑劫，一个一个的发生。刀兵劫持续七日便，疾疫劫持续七月七日，饥馑劫持续七年七月七日。", "ke": "明劫中灾"}, "世间-98": {"jie": "大三灾是火灾、水灾和风灾，第二静虑是火灾顶，第三静虑是水灾顶，第四静虑是风灾顶。\n初静虑寻伺是内灾，第二静虑喜乐为内灾，三静虑动息为内灾。第四静虑没有灾，佛说其是不动地。", "ke": "明大三灾"}, "世间-99": {"jie": "然而第四静虑的器世间也不是常住不灭的，而是与降生该处的有情同时生灭。\n七次火灾后有一次水灾，如此七火一水，循环七次后，第八轮再经历七次火灾后就是风灾。", "ke": "明大三灾"}, "业-1": {"jie": "世间的差别皆由业产生，业可分为思业和思所作业\n思业就是意业，思所作业是身业和语业。", "ke": "明二三业"}, "业-2": {"jie": "身业和语业 具有表业和无表业的特性\n（有部）身表业体为种种不同的身形色，不是“动作”（动色）为体。", "ke": "明五业　　E1 明表无表"}, "业-3": {"jie": "因为一切的有为法，最后都要消灭尽的，因为有最后的尽，所以知道它是有刹那灭的。\n应该没有无因生的法（一切法生待因），如果按照正量部“灭法待因”，就会出现一个法即是生因，又是灭因的矛盾。", "ke": "明身语表"}, "业-4": {"jie": "（经部认为）形色也不是实在有的，否则，便有一个色法——形色，眼根也能取，身根也能取的过失（根只能取相应的境）。\n除了显色的极微以外，没有形色的极微了；有部说的语业是说话的声音。", "ke": "明身语表"}, "业-5": {"jie": "有部用八个理由证明无表色︰三色证，无漏色证，福增长证，非作成业证，“等”字包括了后四（法处色证，八道支证，别解脱戒证，戒为堤塘证。）。\n无表色的能造大种，跟表色所依的大种不一样。", "ke": "证有无表"}, "业-6": {"jie": "欲界第二念的无表色，是依过去大种（初念大种）生的。（所依是过去大种，依是现在大种，依两个大种。）\n有漏的无表色，依自地的大种造；", "ke": "明能造时同异"}, "业-7": {"jie": "无表业没有执受。有等流性，也通刹那性（“亦”言显此有是刹那，谓苦法忍）。从有情身所起，故属有情数摄。\n“散”谓欲界别解脱无表。“依”谓无表所依大种。此散大种，是等流性。又此大种，必有爱心，执为自体，故有执受。“异大生” 为身三、口四，七支无表，一一各别，四大种造。", "ke": "约类以明"}, "业-8": {"jie": "定共戒与道共戒所依大种有长养性、无执受，其七支，是同一四大种所造。\n表业只有等流性；身表业属于身，是有执受。若是语表业，则无执受。", "ke": "约类以明"}, "业-9": {"jie": "无表业是有记(善恶)的，而身语表业及思业通三性，不善的表无表业及意业只有欲界有。\n无表业遍欲界和色界，无色界没有（不现起）；表业只在有寻有伺（欲界及初静虑）、无寻唯伺（中间定）二地有", "ke": "明性界地"}, "业-10": {"jie": "欲界没有有覆无记的表业，因为没有能引生表业的有覆无记心。\n解脱即涅槃，名为胜义善。无贪等三善根及惭、愧二，此五法体性是善，名自性善。", "ke": "明性界地"}, "业-11": {"jie": "相应善，是指与无贪、无瞋、无痴、惭、愧五个法相应的心王心所。自性善及相应善所等起的身语表业、无表业，及俱有的四相、得、二无心定（无想定、灭尽定）等名为等起善。\n与四种善相反的名为四种不善。胜义无记是虚空无为、非择灭无为二常法，是恒常性，名为胜义；非道所证故，名为无记。", "ke": "明三性所由"}, "业-12": {"jie": "等起有两种：因等起（发业前的心），刹那等起（作业时同时生起的心、心所）。\n按照前后次第，因等起名为转，刹那等起名为随转。", "ke": "明等起义"}, "业-13": {"jie": "见所断的烦恼，跟相应的心王，只能作转； 前五识只是自性分别，故不能作转；能缘外门，所以能作随转（跟著意识转）。\n修所断的意识通转和随转。无漏法、异熟生法，不能做转和随转。", "ke": "明等起义"}, "业-14": {"jie": "转有善、恶、无记，每一种转对应的随转可以有善、恶、无记三种。\n特殊的情况：佛的转心是善，则随转心一定是善。有部认为佛的转心也有无记，随转心是善或无记，大众部认为佛没有无记心。", "ke": "明等起义"}, "业-15": {"jie": "无表业有三种：律仪、不律仪、非律仪非不律仪\n律仪有三种：别解脱律仪、静虑律仪、道生律仪", "ke": "明三无表"}, "业-16": {"jie": "别解脱律仪分八种，八种的名字不同，真实的体却只有四个。\n因为有男女根相互转变的不同，而名字也不一样；一个有情身上可以同时有这几种，因为它们之间的“体”互相不违的。", "ke": "明初律仪"}, "业-17": {"jie": "受持五条应当远离的戒，是近事戒；八条是近住戒；十条是沙弥戒；若受持一切所应远离身语戒，是苾刍戒。\n这样安立为近事戒、近住戒、勤策戒、苾刍戒。", "ke": "安立四律仪"}, "业-18": {"jie": "八种每一种都还可以名为尸罗、妙行、业、律仪，四个名字。\n只有受戒时，最初舍掉恶行那一念的表业及表业所生的无表业，名为别解脱，也可名为业道。", "ke": "别释异名"}, "业-19": {"jie": "从比丘到近住这八类人成就别解脱戒。\n得静虑者和得圣者，分别成就静虑律仪和道生律仪。后面两个律仪（定共戒、道共戒），是随心转的。", "ke": "明成三戒"}, "业-20": {"jie": "未至定断欲界九品烦恼的九无间道同时生起的道共戒、定共戒，这两种都名为断律仪。\n正知正念，这两个合起来，名为根律仪，也名为意律仪。", "ke": "明断律仪"}, "业-21": {"jie": "别解脱戒的无表业，只要未舍，恒时都成就现在（法俱得）；", "ke": "约世明成就"}, "业-22": {"jie": "得到静虑律仪，未舍以来，它总是成就过去（法后得）、未来（法前得）。\n得圣的初念苦法忍没有法后得，有法俱得和法前得；正住在定中时，定共戒和道共戒有法俱得，也成就法前和法后得。", "ke": "约世明成就"}, "业-23": {"jie": "非律仪非不律仪中的无表色，第一念成就法俱得，第二念后成就法后得，也有法俱得。\n住在律仪时也可以起染污的无表（如比丘起烦恼造恶业），住在不律仪时也可以起净的无表（恶律仪者发善心，造善业）。", "ke": "约世成处中"}, "业-24": {"jie": "这个无表是处中无表，第一念成就现在，第二念以后成就过去、现在，一直持续到染污和善的势力消除前。\n表业正在作的时候，成就现在；", "ke": "约世成处中"}, "业-25": {"jie": "有覆无记跟无覆无记的表业，只成就现在（法俱得）。\n“恶行”、“恶戒”、“业”、“业道”、“不律仪”五个是不律仪的异名，", "ke": "成就表"}, "业-26": {"jie": "只成表业而没有无表业的情况，是指住非律仪非不律仪的人以微劣心造善恶表业。\n初、二果圣者在来世的住胎位时，过去的表业舍掉了，现在的表业还没生起，只成就无表业而没有表业。", "ke": "成表及无表"}, "业-27": {"jie": "定共戒可依九个定地生起（中间定、四根本定及其近分定）；得圣道者依前面静虑中的六个定地生起道共戒。", "ke": "明得三律仪"}, "业-28": {"jie": "别解脱戒的受持期限只有两种：尽形寿、一昼夜（近住戒）。\n恶戒的期限没有一昼夜，只有尽形寿，跟受持善戒不同。", "ke": "明得三律仪"}, "业-29": {"jie": "受八关斋戒要在日出时，处于下座恭敬心从比丘戒师处求受。\n受戒人要随戒师后而说，要具足受持八支戒才可成为近住；要离开华丽的装饰等产生憍逸处，受持的时间是一昼夜，至第二天日出时。", "ke": "明受方法"}, "业-30": {"jie": "这个八关斋戒里边，戒支有四条，不逸一条，禁支三条；\n离杀盗婬妄四戒支是防性罪的，离饮酒的不逸支是防止失念的，其它三禁支防止憍逸的。", "ke": "明具八支"}, "业-31": {"jie": "没有受五戒的也可得近住戒；没有受过三归的不得近住戒。\n有部认为：受三归时当自称我是邬波索迦等话的时候，便同时发五戒的体了；就像苾刍戒一样，三羯磨竞而得戒。", "ke": "F3明不受近事得近住"}, "业-32": {"jie": "经部问难：如果要具足五戒才名为近事，那为何经上说有持一分、多分等的近事呢？\n有部答：这是就能持来说：五条戒能持一分、二分、多分或满分，也就是说它戒体是五条都有的，但是其能做到的可以是一分、二分等。", "ke": "会经文"}, "业-33": {"jie": "归依三宝中，皈依佛是皈依能成佛的无学法；归依僧是皈依能成僧的学法和与无学法。", "ke": "明三归体"}, "业-34": {"jie": "为什么五戒里边要离邪行，而不是离非梵行呢？因为邪行，是世间最可呵斥的；凡夫容易离开（做到）；圣者得了道共戒，一定不会犯。\n所得的律仪与其受五戒时发的誓是同一性质的；正受五戒时候，发誓对一切有情不做欲邪行，没有发誓对于一切有情不作非梵行。", "ke": "明离邪行"}, "业-35": {"jie": "假定开缘虚诳语戒，于所犯戒，便言我不作，所以对于于戒，多所违越。\n为何五戒中的遮罪，只立不饮酒一条？是为保护不犯其它的律仪。", "ke": "明离虚诳语"}, "业-36": {"jie": "欲界的别解脱律仪从&quot;一切&quot;（根本、加行、后起）一切发罪处得戒，从“二”（情、非情处）得，只从“现”（现在世）的蕴、处、界处得。\n定共戒和道共戒只从根本业道得，过去现在未来三世都可以得。", "ke": "明得处时同异"}, "业-37": {"jie": "律仪是从一切有情发戒，“支”，不一定具足身口七支（如五戒）。“因”，受戒的上中下三种发心也不一定都具足。\n不律仪从一切有情发戒，其七支是全的，因只有一个。", "ke": "明有情支因"}, "业-38": {"jie": "得不律仪由两种因：一是生在不律仪家，从造作不律仪的行为时便发恶戒；二是没有生在不律仪家，当发誓要行不律仪时发恶戒。\n“余”为得处中无表色，有三种方式生起：一、“田”为，诸福田，初施便生；二、“受”，发誓言受持；三、“作”，殷重作意，行善行恶。", "ke": "明得恶处中"}, "业-39": {"jie": "舍别解脱戒：第一，故心舍；第二，命终舍\n第三，转根成二形；第四，断善根；第五，一昼夜过了之后就舍戒（八关斋戒）。", "ke": "舍别解脱"}, "业-40": {"jie": "经部师认为犯了根本戒就舍戒了；法密部认为法灭尽的时候，戒体也就没有了。\n有部认为，犯了根本戒之后，戒体不会失去，因为，犯一条戒，不能舍一切律仪，不过有二名，持戒和犯戒，就像富人，欠债时，名为富人及负债者。", "ke": "舍别解脱"}, "业-41": {"jie": "舍从定里生起来的善法（包括定共戒）有三种方式：由下地生上地或上地生下地舍；定退失舍；命终舍。\n舍道共戒三种方式：证得更高的果位；钝根练到利根；果道退失。", "ke": "舍定道戒"}, "业-42": {"jie": "舍恶戒有三种方式：命终舍；得到别解脱戒；转根成了二形。\n舍处中无表由六种方式：由受断、由势断、由作断、由事断、由寿断、由根断。", "ke": "舍不律仪"}, "业-43": {"jie": "舍欲界非色善法（善心所法等）有二种方式：断善根；生到上界。\n由对治道的力量生起来，便舍掉三界非色染法（烦恼及彼助伴）。", "ke": "舍非色善染"}, "业-44": {"jie": "恶戒只有人趣三洲有，除北俱卢洲没有，还要除去扇搋、半择迦二种黄门和二形人。\n律仪人趣、天趣都有（除北洲、黄门和二形），但是只在人趣三种都有（别解脱、静虑、无漏）。", "ke": "约处明成就善恶律仪"}, "业-45": {"jie": "生在欲界天、色界天有静虑律仪，\n无漏戒在欲、色界天有，并且无色界也有；但是除去中间定、无想定。", "ke": "约处明成就善恶律仪"}, "业-46": {"jie": "安稳业就名为善，不安稳业名为不善，非安稳非不安稳业名为无记。\n福业、非福业、不动业，欲界的善业名为福，", "ke": "明三性业"}, "业-47": {"jie": "欲界的不善业名为非福；色、无色界的善业名为不动业。\n根据所生的处所，它的业果是不动的（比如得了初禅，来世决定感的是初禅的果，而非其它地方；而欲界是五趣杂居地，一地业五趣不定。", "ke": "明福等三业"}, "业-48": {"jie": "顺乐、顺苦、顺不苦不乐三种受业，从欲界到三禅间的善法，名为顺乐受业；\n欲界的不善业，名为顺苦受业。三禅以上的善业名为顺不苦不乐受业。", "ke": "明三受业"}, "业-49": {"jie": "有人说，三禅以下也有顺不苦不乐受业；比如由修中间定的业，将来感生中间禅的异熟报。\n《发智论》里承许顺苦受、顺乐受、顺不苦不乐受三种业，可一时成熟感异熟果。", "ke": "明三受业"}, "业-50": {"jie": "顺受总共有五种：自性顺受、相应顺受\n以及所缘顺受、异熟顺受、现前顺受；一共有这五种的差别。", "ke": "明三受业"}, "业-51": {"jie": "业有定业、不定业\n定业有三种:顺现受、顺生受、顺后受。\n有人说业有五种（把不定业又分两种：异熟定时不定、异熟与时俱不定）；譬喻论师，把业分了八种（把“时不定”又分现受、生受、后受），并四料简分别。", "ke": "明四种业"}, "业-52": {"jie": "论主认为顺现、顺生、顺后、不定受，这种四业的分法好；四业容许在同一时间全部做；能引众同分（作引业）的只有三个业（除顺现受）。\n诸界、诸趣都能造四种业。但是地狱里边，要除去善的顺现受业。", "ke": "明差别"}, "业-53": {"jie": "不退的离欲凡夫跟离欲圣者，对已离开的欲界，异生不会造顺生受业了；\n（接上）圣者不造顺生和顺后业。并“欲”是离欲界圣人（三果），“有顶”是离有顶烦恼圣人（四果），他们虽有退堕，亦不造欲界、有顶，生、后二业，同前不退圣。", "ke": "明差别"}, "业-54": {"jie": "欲界的中有，能造二十二种业。\n都是顺现受业，因为中有跟生有的同分是同一类的，也是同一引业感得。", "ke": "明中有造业"}, "业-55": {"jie": "由极重烦恼，或极清净善心，或是恒常造的业，\n对于功德田所造的业，对父母行损害，这些都是决定感果的定业。", "ke": "明定业相"}, "业-56": {"jie": "田、意殊胜的业，以及生于此地的阿罗汉及不还者，过去所造的异熟定而时不定的业，必定现世感果。（三果、四果，因于此一生命结束后，不再到此地来受生，所以所有以前所作的诸业，如果是异熟定而时不定的，必定招现法果）", "ke": "明现法果业"}, "业-57": {"jie": "对佛为上首的僧团，及灭尽定、无诤定出来的人，\n以及刚刚从慈心定出定，或初见道（预流果），或刚证四果（修道出）的人，如果在这几类人身上造善恶业，即刻就受报。", "ke": "明业即受"}, "业-58": {"jie": "中定以上乃至有顶的善业（无寻善业），只感心受果，不感身受果。\n恶业，只感身受苦报。这是“受”业感果的不同情况。", "ke": "明二受"}, "业-59": {"jie": "五识身无分别故，必无心狂，所以心狂，唯在意识。由五因让有情心狂：一、异熟业\n二、惊怖；三、伤害、四、乖违（四大不调）、五、忧愁。在欲界五趣都有狂，除了北拘卢洲。", "ke": "明心狂等"}, "业-60": {"jie": "依谄曲生的身口意三业，名为曲业；依瞋起的，名为秽业；依贪起的名为浊业。\n依据黑黑等不同的种类，（经中）提到四种业。", "ke": "明曲秽浊"}, "业-61": {"jie": "分别是恶业、色界善业、欲界善业，以及能断除这三种业的无漏业\n应当知道：按次第，恶名黑黑业；色界善业名白白业；欲界善业名黑白黑白业，即“俱；能断除这三种业的无漏法，名非黑非白业，即“非”。", "ke": "明四业"}, "业-62": {"jie": "见道的四法忍，断欲界修惑的前八无间道，\n共十二个无漏思心所，能断除纯黑业。", "ke": "明无漏断"}, "业-63": {"jie": "断欲界修惑的第九无间道的思心所，以及断色界修惑，即，四静虑的每一个第九个无间思\n前者（离欲）能断除欲界的黑白黑白业（欲界善业）和黑黑业，后者（断色界修惑）能断除色界的白白业。", "ke": "明无漏断"}, "业-64": {"jie": "有人说顺地狱受的业是黑黑业，其它欲界的业是黑白黑白业。\n还有人说欲界见所断的业是黑黑业，欲界修所断的业是黑白黑白业。", "ke": "叙异说"}, "业-65": {"jie": "无学的身业、语业，以及其意识；这三者即是三牟尼。\n三清净，应当知道即是身语意三种妙行", "ke": "明三牟尼等"}, "业-66": {"jie": "三恶行，指恶的身、业、意业，\n以及贪瞋邪见；三妙行与三恶行相反。", "ke": "明三恶行等"}, "业-67": {"jie": "经上所说的十业道，含摄在三恶行和三妙行中。", "ke": "明业道体"}, "业-68": {"jie": "十恶业道中，有六个（除邪淫及意三恶）决定是有无表业的。彼六恶业，若自作，则表、无表业二种都有；邪婬，决定是表、无表业两种都有。\n善业道中，身三口四七业道，假使从他人受得的（如受别解脱戒），则表、无表业两种都有（即简别非受生的，如处中无表，就不一定是两个都有）；定共戒只有无表业。", "ke": "约根本明"}, "业-69": {"jie": "业道的加行必有表业，无表业或有，或没有。\n业道的后起，其表、无表业的有无情况，与加行相反。", "ke": "据前后辨"}, "业-70": {"jie": "贪、瞋、邪见，意三业道（没有加行），是从贪、瞋、痴三不善根无间生出的（如贪业道，从贪无间生：先起个贪心，跟著生起贪的业道）。\n十善业道，在加行、根本、后起三位，都是从无贪、无瞋、无痴三善根生（三善根须同时具足）。", "ke": "据前后辨"}, "业-71": {"jie": "杀生、粗恶语、嗔恚三个业道，皆以瞋心究竟。\n偷盗、邪婬跟贪三个业道，皆以贪心究竟。", "ke": "明究竟业道"}, "业-72": {"jie": "邪见业道，是以痴心究竟（因上品痴是邪见）。余下的虚诳语、离间语、杂秽语三个业道，由贪、瞋、痴三不善根中任一个都可究竟。\n十业道分别是依有情、资具、名色、名身等这些地方生起的。", "ke": "明究竟业道"}, "业-73": {"jie": "假使能杀者跟所杀者同时死，或者是能杀者在所杀者之前死，则能杀者没犯杀生根本业道；因为与他杀人依止的那个身体已经不是同一个了。\n一个军队或猎队假使是同一目的去杀生，那么任随其中一人杀了生，其他每个人都成就如同杀生者一样的杀业道。", "ke": "杀已非业道"}, "业-74": {"jie": "杀生业道需五缘具足才成就：起故杀心，对境是他有情，作他有情想，起杀加行，杀的对象没有错。\n不与取业道，对境是他财物，加行是用暴力（如抢劫）或者偷的方式，取来属于自己所有。", "ke": "明杀"}, "业-75": {"jie": "欲邪行（邪淫）包含四种，都是在一些不应当行婬的情况下而行的情况（非境、非道、非处、非时）。\n染污心、所说与所想不一样、说话、对方理解，以上条件具足，便成虚诳语。", "ke": "明淫"}, "业-76": {"jie": "六识里，眼识、耳识、意识，以及其它鼻、舌、身三识所证到的；\n按著这样的次第，依次名为见（眼）、闻（耳）、知（意）、觉（鼻、舌、身）。", "ke": "明见闻等"}, "业-77": {"jie": "以染污心说毁坏他人和合的语言，名为离间语。", "ke": "明离间等三语"}, "业-78": {"jie": "其他论师说，只要不同于虚诳语、粗恶语、离间语三种染污语外，其他所有染心发的语，都属于杂秽语；比如谄佞语、歌咏、以不正见说的话等。\n想要非理贪取他有情的财物名为贪业道。对他有情起憎恚心，欲行逼恼或伤害，名瞋业道。", "ke": "明离间等三语"}, "业-79": {"jie": "拨无善恶因果及谤圣等的见，名为邪见业道。\n十业道中意三只是道，身口七支既是业又是道。", "ke": "明意业道"}, "业-80": {"jie": "只有邪见能够断善根，所断的善根是欲界的生得善。\n拨无善恶因果，一切的邪见都能断善根；断善根是一品品渐次断；断善根时，善根和律仪两个是一起断掉了。", "ke": "义便明断善"}, "业-81": {"jie": "只在人趣三洲，并且唯有男、女身能断善根；仅见行人可断善根，断善根是以善根的非得为体的。\n断善根的人产生因果可能是有的疑心时，善根就续起了；善根续起时是九品顿现，除去此生造了五逆的人。", "ke": "义便明断善"}, "业-82": {"jie": "业道与发动业道的刹那等起思同时生起的情况：不善业道可以一个乃至最多八个与思心所俱转（同时生起）。\n善业道可以有一至十个与思俱转；但是一俱转、八俱转、五俱转没有。", "ke": "明业道与思俱转"}, "业-83": {"jie": "在地狱里，恶业道的麤恶语、杂秽语、瞋恚，三个业道的现行、成就都有。\n地狱里贪心、邪见只成就，不现行；北俱卢洲成就后三，即贪、瞋、邪见，不现行。", "ke": "约处成善恶"}, "业-84": {"jie": "杂秽语北俱卢洲通现行、成就；欲界其他地方，十业道都通现行、成就。\n善业道在一切处都有，其中无贪、无瞋、正见，三个通现行、成就。", "ke": "约处成善恶"}, "业-85": {"jie": "在无色界或无想天，身三口四七支只有成就\n七支在其它地方通现行、成就；但地狱、北洲要除掉。", "ke": "约处成善恶"}, "业-86": {"jie": "每一种业道都可招感异熟、等流、增上三种果。\n以杀生为例，杀时使对方受苦、断命、失去威仪的缘故，以次受上述三种果。", "ke": "明业道三果"}, "业-87": {"jie": "从贪心生的身、语业名为邪命，邪命最难除掉，所以单独立名称为邪命。\n有人说为了自身活命的资具而生贪，叫邪命；论主认为这种观点跟经上说的话不合，所以不合理。", "ke": "别明邪命"}, "业-88": {"jie": "以有漏无间道断烦恼的业，能感五个果。\n以无漏无间道断烦恼的业，能感四个果，除异熟果。", "ke": "总明诸业果"}, "业-89": {"jie": "除断道外的有漏善、恶业，能感四个果，除离系果。\n除断道外的无漏业跟无记业，各能感三个果，除前面所除掉的异熟和离系。", "ke": "总明诸业果"}, "业-90": {"jie": "善、恶、无记业以善、恶、无记法为果：善业感善法为果，有4个果；感无记法为果，有2个果，感不善法为果有3个果。\n无记业感善恶无记法为果分别是2.3.4个果；恶业感善恶无记法为果分别是2.3.3个果", "ke": "三性相对果"}, "业-91": {"jie": "三世业（过去业、现在业、未来业）感三世法为果，过去业分别感4个果；现在业感未来果也是一样（4个果）。\n现在业感现在果是2个果；未来业感未来果是3个果。", "ke": "明三世果"}, "业-92": {"jie": "某地造业，同地感果有4个果；异地感果有2或3个果。\n有学造业，分别以有学法、无学法、非学非无学法为果，分别都是3个果；无学造业，对应以上三种法分别感1.3.2个果。", "ke": "明诸地果"}, "业-93": {"jie": "非学非无学造业，对应以上三种法分别感2.2.5个果。\n见所断业、修所断业、非所断业三种业，分别以见所断法、修所断法、非所断法三种法为果；", "ke": "明学等三果"}, "业-94": {"jie": "见所断业，分别以见所断法、修所断法、非所断法三种法为果，各自是3.4.1个果；修所断业，对应以上三种法分别感2.4.3个果。\n非所断业，对应以上三种法分别感1.2.4个果。", "ke": "明见断等三果"}, "业-95": {"jie": "染污的业名为不应作业；还有说违背轨则、威仪的也名为不应作。\n应作业是和不应作业相反（不染污的、善的，或加上合轨则、合威仪的）。既非应作业又非非应作业是第三种（非应作非不应作业）。", "ke": "释本论所说三业"}, "业-96": {"jie": "一个引业只能引一生，有多个业圆满。\n两个无心定（无想定和灭尽定）以及善恶法的得，不能作引因，只可作满因。其它善恶有漏法，都有引和满的作用。", "ke": "明业感多少"}, "业-97": {"jie": "三障（业障、烦恼障、异熟障）分别是五无间业、数数现行的烦恼。\n以及一切的恶趣、北拘卢洲和无想天。", "ke": "明障体"}, "业-98": {"jie": "人趣中除北拘卢的余三洲都有无间罪，其它地方没有；三洲里的扇搋（黄门、二形之类）也没有无间罪。\n原因是因为父母对他们少恩，他们对父母的惭愧心也轻；除无间业之外，其它烦恼障跟异熟障，五趣都有。", "ke": "约处辨"}, "业-99": {"jie": "五无间罪的体，四个是身业，一个是语业。\n四身业里，杀父、杀母、杀阿罗汉三个是杀业；破僧是虚诳语业；出佛身血是杀生加行，不成根本业道。", "ke": "明业障体"}, "业-100": {"jie": "僧破的体是不和合，是个心不相应行法。\n僧破本身是无覆无记的，是由所破的僧众所成就的。", "ke": "明不相应行"}, "业-101": {"jie": "能破的人所成就的唯是虚诳语罪。\n所感的果报：处所是无间地狱受苦，时间是一劫。随所造的罪越多，受的苦也越多。", "ke": "明能破成时处"}, "业-102": {"jie": "能破僧者，须是比丘，且是见行人，持戒清净；破僧要与佛不在同一处，被破的比丘是凡夫。\n忍可除了佛以外还有大师，并且除了佛的八正道以外还有更殊胜的道时，僧便正式被破了。僧被破后，时间不会超过一宿便会复合。", "ke": "明具缘成破僧"}, "业-103": {"jie": "破僧须要在南赡部洲，并且最少是九个比丘，方能破法轮僧。\n单是破羯磨僧不破法轮僧的话，那么三洲都有，最少八个比丘。", "ke": "明破二僧别"}, "业-104": {"jie": "佛初转法轮未久、最后灭度前、疱前（邪戒、邪见的疱没有起之前）、双前（第一双弟子出现前）、佛灭度后、没有结界的时候。\n这六个时间段，没有破法轮僧。", "ke": "明无破法轮时"}, "业-105": {"jie": "由弃父母恩田、坏功德田故，而成无间罪。假使父母的男女性别转变，杀了也同样成逆罪。\n真正的母是血分所成，是其本生母（非后母）；“无”误杀父母不成逆。“等”者等取害余人，无有表。“或有”，若害阿罗汉，无简别故，亦有逆罪。", "ke": "明成逆缘"}, "业-106": {"jie": "非以杀心，但起打心而出佛血，不犯无间罪。如果被杀害者，在正被杀时不是阿罗汉，而临死时证了阿罗汉，杀者不犯无间罪。\n如发欲害父母的杀心，而尚未正式的兴害父母，是为无间加行。无间加行，假使必定成就，那在中间决定没有离染得果的可能，因为彼业殊胜，于第二生中，必受其果报，而离染道及得果道，又不能令彼业道不起，所以决定无离染得果。", "ke": "明成逆缘"}, "业-107": {"jie": "破僧的虚诳语罪，是一切罪里边最大的。\n能够感生第一有（有顶天）的意业，是能感世间善法中最大果的业。", "ke": "明罪重大果"}, "业-108": {"jie": "跟母亲或者是无学尼做不净行，杀住定菩萨，\n杀有学圣者，夺取僧团维持和合生活的资具，", "ke": "明无间同类"}, "业-109": {"jie": "破坏佛塔；以上六种罪都是无间罪的同类罪。\n将得忍位时，或要得不还果时，或要证无学果时；这三时，异熟业会障碍他们。", "ke": "明无间同类"}, "业-110": {"jie": "菩萨修三十二妙相业时，得名为住定菩萨。\n住定，有以下六种内涵（1）生善趣定（常生人天，非三恶趣）；（2）生贵家定（常生婆罗门，或刹帝利巨富长者家）；（3）具根定（于贵家中，常具殊胜六根，无缺减）；（4）男定（常受男子身，不为女身）；（5）念定（常能忆念宿世因缘，得宿命通）；（6）坚固定（所作善事，利乐有情，常无退屈）。", "ke": "明住定位"}, "业-111": {"jie": "修妙相，只有南瞻部洲的男身，并要现前亲对佛修。要观佛起思，是思所成慧所修成（不是闻慧、修慧）。\n修的时间是在三大阿僧祗劫外，另需一百大劫来修妙相业", "ke": "明修相业"}, "业-112": {"jie": "菩萨于三无数劫中，初无数劫，供养七万五千佛。第二无数劫供养七万六千佛。第三无数劫，供养七万七千佛。", "ke": "明佛数"}, "业-113": {"jie": "菩萨于三无数劫一一劫满时，所遇到的佛，从后向前依次是：于第三无数劫满时，逢胜观佛；", "ke": "明所逢佛"}, "业-114": {"jie": "菩萨但由悲心怜悯众生而普遍地布施自己的一切（此时布施波罗蜜修习圆满）。\n菩萨被折损身体时，没有一点忿恚之心（此时戒、忍二波罗蜜修习圆满）。\n专诚瞻仰以妙伽陀精进赞叹底沙佛（精进波罗蜜多圆满）；邻近无上菩提的佛位（起金刚喻定，定慧波罗密多修习圆满）", "ke": "明六度圆"}, "业-115": {"jie": "六波罗蜜多，分别在这四个位次修习圆满（即：初施位，无忿位，精进位，次无上位）。\n这四个位次，分别对应六波罗蜜多修圆满的数量，分别是一（施度）、二（戒、忍度）、一（精进度）、二（定、慧度）；", "ke": "明六度圆"}, "业-116": {"jie": "施，戒，修这三类，根据三者各自的情况\n分别名为施类福业事，戒类的福业事，修类的福业事；他们的名字、差别就跟业道一样", "ke": "类摄余蕴 · 类摄余蕴"}, "业-117": {"jie": "由无贪引发的身语业而完成的舍财名为布施，是为了供养三宝或饶益有情。\n身语二业和能发的无贪心是布施的体，布施可以得到大富的异熟果。", "ke": "明布施"}, "业-118": {"jie": "布施有四种：自利；利他；自他俱利；自他俱不利\n由于“主、财、田”的不同，布施的果报也不同。", "ke": "明施益差别"}, "业-119": {"jie": "由布施的主体是否具足信等七圣财，则布施的功德有差别；施主以敬重、自手、应时、无损四种态度来布施，\n对应感得尊重、广爱、应时、难得四种果报。", "ke": "明主异"}, "业-120": {"jie": "布施的财物颜色好，感得身相长得好；香味具足，会感得好名声。\n布施的财物味道好，会感得被大家喜爱的果报；如果财物的触受好，感得身体柔软，随时生乐触。", "ke": "明财异"}, "业-121": {"jie": "布施的对境（田）有趣、苦、恩、德四种差别，所得果报也不同。\n最殊胜的布施有三种：无学供养无学；菩萨为了普利有情而布施；为得涅槃而布施。", "ke": "明田异"}, "业-122": {"jie": "父母、病人、法师、最后身菩萨\n上述四类人虽然还是凡夫，但布施他们而得的功德也是无量无边的", "ke": "明施果无量"}, "业-123": {"jie": "根据后起、田、根本、加行、思、意乐\n业的轻重由这六个因来判定：后起、田、根本、加行、思、意乐的上、下品，决定了果的上下品。", "ke": "明业轻重相"}, "业-124": {"jie": "经过审思后而造的业，造圆满的业，没有忏悔对治的业\n造业的当下，又同时再做其它相同善恶性的业，定感异熟果的业，具足以上五因的名为增长业", "ke": "明造作增长"}, "业-125": {"jie": "供养佛塔虽然佛塔没有受用，但仍能得到舍类福，就像我们修慈悲喜舍四无量心一样，同样所缘的有情也没有受用，但修者仍能得福。\n对方的这个田是不好的，但是你只要有好的心布施的话，也是得到好的善的可爱的果。种子和果是不会颠倒的。但是果的大小却和田有关系。", "ke": "明施制多福"}, "业-126": {"jie": "离开犯性罪跟遮罪\n名为戒；性戒和遮戒各自都有表、无表二种色。\n“非犯戒坏”，没有犯性戒、遮戒；“非犯戒因坏”不为犯戒的因坏（烦恼）；“依治”，依四念住对治；“依灭”，一切持戒功德回向涅槃。这样子持戒是清净。“等”字代表还有其它的说法。", "ke": "明戒"}, "业-127": {"jie": "定中的善名为修，因为定中最能熏习改变我们的心。\n戒类福和修类福，从它殊胜的、主要的一面来说；按次第，戒类福感生天果，修类福感解脱果。", "ke": "明修"}, "业-128": {"jie": "能感得一劫（此处指四十中劫为一劫）在天上享受，即为一个“梵福”的福量。“等”是指还有其他的说法：有部说，是前面修妙相业时的一个福量。\n法布施，是如实无颠倒地、无染污心地讲说辨析三藏十二部。", "ke": "明梵福量"}, "业-129": {"jie": "顺解脱分、顺福分、顺抉择分三种善。", "ke": "明顺三分善"}, "业-130": {"jie": "如理起各自（书印等）的加行业，他们的体性是所发的身语意三业以及能发的受想行识四蕴\n依先后次第，书印的体是身业等五蕴、算文的体是语业等五蕴、数的体是意业等四蕴。", "ke": "明书印等"}, "业-131": {"jie": "无漏善法又名为妙，指道谛和灭谛；欲界染污法又名为有罪、有覆、劣三个名字，指不善和有覆无记法。\n善的有为法（圣道）又名为应习，即应该修习的；解脱（涅槃），又名为无上。", "ke": "明诸法异名"}, "随眠-1": {"jie": "随眠是三有的根本\n按随眠的差别可以分成六种\n以及无明、见、疑", "ke": "明增数"}, "随眠-2": {"jie": "六种随眠由于贪的不同（欲贪、有贪）可以分成七种\n有贪是上二界的贪\n是由于贪着定中的境界而生\n立有贪是为了遮止上二界是解脱处的想法", "ke": "明七随眠"}, "随眠-3": {"jie": "六种随眠由于见的不同可以分成十种\n见的不同可以分为身见\n边执见、邪见\n见取和戒禁取", "ke": "明十随眠"}, "随眠-4": {"jie": "六种烦恼根据见的行解、五部和三界的差别\n可以分成九十八随眠\n欲界的见苦、见集、见灭、见道以及修所断的烦恼\n数量分别是10、7、7、8、4", "ke": "明九十八随眠"}, "随眠-5": {"jie": "按照上面的顺序，依次缺少的是\n见集和见灭缺三个见，见道缺两个见，修所断缺见和疑\n其他的和欲界一样", "ke": "明九十八随眠"}, "随眠-6": {"jie": "法忍和类忍所断的烦恼\n有顶地的只有见道能断\n其他地的通见断和修断", "ke": "明见修断"}, "随眠-7": {"jie": "身见是执着有我和我所，边见认为有断和常\n邪见是拨无因果，见取是以劣为胜\n戒禁取是非因谓因，非道谓道\n以上是五见的自体", "ke": "明五见"}, "随眠-8": {"jie": "对于大自在天等\n他们不是这个世界所生的因，而妄执为因\n这种戒禁取是从常见和我见中生出来的\n所以属于见苦所断", "ke": "别释戒禁取"}, "随眠-9": {"jie": "常乐我净四种颠倒的自体\n是从身见、边见和见取见所生\n立四种颠倒是因为他们一向倒、推度性、妄增益的缘故\n不立想颠倒和心颠倒是因为想和心都是随见的颠倒", "ke": "明四倒"}, "随眠-10": {"jie": "慢有七慢和九慢，九慢是从七慢中的三个慢安立的\n都通于见断和修断\n圣者对于杀生等烦恼\n虽然属于修所断，但是见道后不会再起现行", "ke": "明七九慢"}, "随眠-11": {"jie": "对于慢中的我慢等\n以及不善的恶作\n圣者虽然没有完全断除，但不会起现行\n是因为这些烦恼都是见和疑所增益的", "ke": "明未断不起"}, "随眠-12": {"jie": "见苦和见集所断的烦恼中\n五见、疑以及相应无明\n能够遍行自界自地", "ke": "诸门分别"}, "随眠-13": {"jie": "十一遍使中除去身见和边见\n其他九个烦恼能缘上二界\n除了得，其他的生住异灭等随行法\n也是属于遍行所摄", "ke": "明遍行非遍行"}, "随眠-14": {"jie": "邪见、疑和相应的无明\n以及不共无明\n这六个能缘无漏法", "ke": "明遍行非遍行"}, "随眠-15": {"jie": "其中缘灭谛的三个\n只能缘自地的灭\n缘道谛的三个，能缘六个地或九个地\n能缘六或九地是因为法智和类智对治不能，不同地所生智能互为同类因", "ke": "明有漏无漏缘"}, "随眠-16": {"jie": "不是无漏缘惑\n是因为他们无漏法不是应远离的（简贪），不是怨境（简瞋）\n是非高举的（简慢）、是清净的（简戒取）、是最胜的（简见取）", "ke": "明有漏无漏缘"}, "随眠-17": {"jie": "没有断除的遍行随眠\n对于自地五部都能所缘随增\n不是遍行的随眠只能于自部\n所缘随增", "ke": "明二随增"}, "随眠-18": {"jie": "无漏缘惑和上缘惑不能所缘随增\n因为他们的所缘境不摄自身，而且与烦恼相相违\n烦恼于其所有的相应法\n都相应随增", "ke": "明二随增"}, "随眠-19": {"jie": "上二界的烦恼\n以及欲界的身见和边见\n以及与他们相应的无明，都是无记性的\n其余的都是不善性的", "ke": "明二性分别"}, "随眠-20": {"jie": "不善的根是欲界的\n无记的根有三个\n无记的贪、无明和见", "ke": "明根非根"}, "随眠-21": {"jie": "因为疑有不定性，慢有高举性，所以不立为根\n经部安立四种无记根\n分别是无记的贪、见、慢和无明\n虽然上界定中的贪、见、慢都属于无明所摄，但因相不同安立为四个", "ke": "明无记根"}, "随眠-22": {"jie": "回答的方式有四种：一向记、分别记\n反诘记和舍置记\n如人问死，问生，问人殊胜与否，分别对应前三种回答\n若问我与五蕴为一为异，则应舍置不答", "ke": "因便明四记事"}, "随眠-23": {"jie": "对于所缘事中\n过去或现在若已经生起的话，则只系所缘之事\n若是未来的意识所摄，则可以遍行三世", "ke": "约世明能系"}, "随眠-24": {"jie": "若是前五识所摄在未来可以生起的，则只系自世\n不能生起的也可以遍行三世\n其余过去和未来的，也可以遍行三世\n现在正在缘境的只能系现在世", "ke": "约世明能系"}, "随眠-25": {"jie": "安立三世实有是因为佛说三世有\n“意识由过去的意根和法境二缘生”的教证，及有境有果两个理证\n说明三世是实有\n所以说一切法是实有", "ke": "明三世有无"}, "随眠-26": {"jie": "如何分判三世，有四种说法\n类不同、相不同、位不同和观待不同\n第三位不同从作用的角度\n来安立三世，这种说法最善", "ke": "敍说定宗"}, "随眠-27": {"jie": "是什么阻止了未来法生起，现在起的作用又是什么将其引生\n有部救法体跟作用无异，经部破那三世就不能安立了。\n经部说如果不承认现在实有，过未不存，则三世就不能成立\n论主调侃有部，有部说，法性甚深，我不能答但不能说错。", "ke": "正破"}, "随眠-28": {"jie": "对于见惑，如果见苦的烦恼已经断除\n其他（见集）的遍行随眠仍然能系缚苦谛\n对于修断的烦恼，前品已经断除\n其余品的烦恼仍然能系缚前品", "ke": "约断明离系"}, "随眠-29": {"jie": "见苦、见集和修所断的法\n如果是欲界系的\n则欲界的苦集修和色界的修所断相应的识都能缘\n以及无漏识也能缘", "ke": "明惑随增"}, "随眠-30": {"jie": "色界的苦集修所断的法，色界和欲界苦集修相应的识能缘\n无色界修所断相应的识和无漏识也能缘\n无色界的苦集修，有三界的识能缘", "ke": "正明惑随增"}, "随眠-31": {"jie": "见灭道所断的法\n除了苦集修相应的识能缘，还要增加自部相应的识\n无漏法，三界的识都能缘\n分别是见灭、见道和修所断识，以及无漏识。", "ke": "明有漏无漏缘"}, "随眠-32": {"jie": "有随眠心分为两种\n一种是有染的，一种是无染的\n有染的有随增和不随增两种情况\n无染的只有所缘随增一种情况", "ke": "明有随眠心"}, "随眠-33": {"jie": "烦恼生起的次第是无明生疑，疑生邪见，邪见生身见\n身见生边见，边见生戒禁取，戒禁取生见取\n由前面的烦恼引生后面的烦恼", "ke": "明次第起"}, "随眠-34": {"jie": "烦恼生起三因：第一是随眠未断\n第二是与烦恼相应的境现前\n第三是生起非理作意\n所以说烦恼的生起是有因缘的。", "ke": "明起惑因"}, "随眠-35": {"jie": "欲界的烦恼加上十缠\n除了无明，其余的叫做欲漏\n有漏是上二界的\n除了无明以外的其他烦恼", "ke": "明漏等四门"}, "随眠-36": {"jie": "因为色界无色界的烦恼同是无记的，而且缘定境而生\n又都是属于定地，所以合称为有漏\n无明是三有的根本\n所以别立为无明漏", "ke": "出体"}, "随眠-37": {"jie": "瀑流和轭也是一样\n比漏多安立一个见瀑流（轭），因为见有推度性，所以比较利\n因为见不随顺住的含义（漏有住的含义）\n所以不在漏中单独安立见漏", "ke": "出体"}, "随眠-38": {"jie": "在欲轭、有轭中分别加上欲界和上二界的无明\n以及把见分为两个——见取和戒禁取，一共是四取\n无明不单独安立为取\n是因为无明昏寐，没有取着的能力", "ke": "出体"}, "随眠-39": {"jie": "随眠的含义是微细、所缘随增、相应随增\n随逐有情、随时系缚众生\n漏的含义是住和流，瀑流的含义是漂，轭是合和有情，取是执取\n这些是随眠的含义", "ke": "释名"}, "随眠-40": {"jie": "烦恼按照结的差别\n还可以分为五种\n九结中，因为物等和取等\n立了见结和取结", "ke": "明结等五门"}, "随眠-41": {"jie": "有部认为是因为嫉悭唯不善性\n以及二者是自在起的\n所以缠中只有嫉悭\n立为两个结", "ke": "明九结"}, "随眠-42": {"jie": "论主认为有七个原因：嫉悭数数现行\n能够遍显随烦恼\n能够恼乱出家在家、天阿素罗、人天和自他部所以立为二结", "ke": "明九结"}, "随眠-43": {"jie": "还有五顺下分结\n由于欲贪和瞋而不能超出欲界\n由于有身见、戒禁取和疑，即使超出欲界还会回来\n由于摄门和摄根的缘故，说三即是说六", "ke": "明五下分结"}, "随眠-44": {"jie": "还有一种解释，不能解脱的原因一个是不想解脱\n或者是对所走的道有疑及迷路\n这些能障碍解脱\n所以只说断身见、戒禁取和疑这三个", "ke": "明五下分结"}, "随眠-45": {"jie": "顺上分结也有五个\n色界和无色界的两个贪\n掉举、慢和无明\n能令有情不超出上界", "ke": "明五上分结"}, "随眠-46": {"jie": "贪缚、瞋缚和痴缚是由于乐、苦、舍三种受\n随眠的含义前面已经说过了\n根本烦恼以外的都是随烦恼\n其体是染污心所，行蕴所摄", "ke": "明三缚"}, "随眠-47": {"jie": "八缠包括无惭、无愧\n嫉、悭和悔、睡眠\n十缠的话还要加上忿和覆", "ke": "明缠"}, "随眠-48": {"jie": "无惭、悭和掉举\n是从贪而生\n是从无明而起", "ke": "明缠"}, "随眠-49": {"jie": "悔是疑的等流，覆有诤论，或贪等流或痴等流或贪痴等流\n六垢包括恼", "ke": "明缠"}, "随眠-50": {"jie": "恼是从见取而起\n谄是从诸见而生", "ke": "明烦恼六垢"}, "随眠-51": {"jie": "缠中的无惭、无愧以及睡眠\n其余的缠加上六垢\n因为是自在起的，所以唯修所断", "ke": "诸门分别"}, "随眠-52": {"jie": "欲界的睡眠、昏沉、掉举通不善性和无记性\n上界的随烦恼都是无记性\n谄和诳在欲界和初禅有\n昏沉、掉举、憍，这三个烦恼三界都有，其他的只有欲界有", "ke": "三性分别"}, "随眠-53": {"jie": "见所断的慢和睡眠\n以及自在起的随烦恼\n都是依意识起的\n其余的随烦恼都是通依六识而起", "ke": "明六识相应"}, "随眠-54": {"jie": "欲界的诸烦恼\n贪和喜乐相应\n邪见与忧和喜相应", "ke": "明五受相应"}, "随眠-55": {"jie": "疑与忧相应，其余五个与喜受相应\n一切根本烦恼都与舍受相应\n上二界的烦恼皆随其所应\n此地中哪有些识，烦恼就可以与这些识所对的受相应", "ke": "明本惑相应"}, "随眠-56": {"jie": "所有的随烦恼中\n嫉、悔、忿、恼\n加上害、恨与忧受相应", "ke": "明随惑五受相应"}, "随眠-57": {"jie": "谄、诳、睡眠及覆\n通忧、喜相应\n其余四个，与所有受都相应", "ke": "明随惑五受相应"}, "随眠-58": {"jie": "五盖只在欲界有\n因为食同、治同和用同的缘故\n昏眠和掉悔各是两个烦恼立为一个盖\n因为分别障碍五解脱蕴，所以是五个盖", "ke": "明五盖差别"}, "随眠-59": {"jie": "断见惑的方式有三种，分别是遍知所缘故断\n断彼能缘故断\n断彼所缘故断\n断修惑的方式是起对治道断", "ke": "明惑灭"}, "随眠-60": {"jie": "对治有四种方式\n分别是断对治、持对治、远对治和厌对治\n应当知道，从烦恼所缘随增的角度\n于所缘境烦恼不随增，可以说烦恼断除了", "ke": "明四种对治"}, "随眠-61": {"jie": "远的特性有四种\n叫做相远、治远、处远和时远\n举例来说，比如大种、尸罗\n不同的地方、过去和未来二世等", "ke": "明四远性"}, "随眠-62": {"jie": "已经断掉的烦恼不需要再断\n但离系的择灭得可以重新得\n重得的时间是在治生时、得果时\n和练根时，六个时间", "ke": "明断惑得灭"}, "随眠-63": {"jie": "断遍知一共有九个\n欲界见苦和见集断合立一个遍知\n见灭和见道断各立一个遍知，一共三个遍知\n上界也是立三个遍知", "ke": "明九遍知"}, "随眠-64": {"jie": "剩下的遍知有五顺下分结尽遍知\n色爱尽遍知和一切结永尽遍知，共三个\n九个遍知中，属于忍果的有六个\n剩下三个是智的果", "ke": "列九遍知名"}, "随眠-65": {"jie": "未至定能得一切遍知\n色界根本地能得五个遍知或八个遍知\n无色界的近分定能得一个果\n无色界前三个根本定也只能得一个果", "ke": "明六对果"}, "随眠-66": {"jie": "世俗道能得二个果，无漏道九个果都能得\n法智能得三个果，类智能得两个果\n法智品能得六个果\n类智品能得五个果", "ke": "明六对果"}, "随眠-67": {"jie": "必须得到无漏的择灭得\n以及有顶地缺一部\n加上灭同类因和遍行因，以及越界\n由以上四个条件，立了九个遍知", "ke": "明建立遍知缘"}, "随眠-68": {"jie": "在见谛位可能一个遍知也不成就\n或者成就一个到五个\n修道位能成就六个或一个或二个\n无学只成就一个", "ke": "明成就遍知"}, "随眠-69": {"jie": "因为越界和得果两个原因\n有两个地方立了集遍知（五顺下分、一切结尽）\n舍遍知的情况有舍一个、二个、五个或六个\n得遍知的情况与舍相同，只是没有得五个这种情况", "ke": "明集遍知"}, "贤圣-1": {"jie": "随眠品已经说明烦恼的断除\n是由见谛道断和修道断\n见道只能是无漏道\n修道可以通有漏道和无漏道两种", "ke": "明道体性"}, "贤圣-2": {"jie": "四谛的名称，界品已经说过了\n就是苦谛、集谛、灭谛和道谛\n它们的体也和界品说明的一样\n四谛的次第是随着现观的次第来安立的。", "ke": "明道所证谛"}, "贤圣-3": {"jie": "苦谛之所以名为苦谛，是由于苦苦、坏苦和行苦这三苦与之和合的缘故。\n一切有漏法，如其所应，与三苦合，都称为苦谛\n可意的有漏法与坏苦相合，非可意的有漏法与苦苦相合\n其他的有漏法与行苦相合", "ke": "别明苦谛"}, "贤圣-4": {"jie": "一个法被物理破坏后便消失的，称为世俗谛\n用智慧分析后消失也称为世俗谛\n比如瓶子（可以打破）、水（可以慧析），这样的法都是世俗谛\n除了这些法，其他的名为胜义谛", "ke": "明二谛"}, "贤圣-5": {"jie": "将要趣入见道\n首先要持戒\n然后勤修闻思修三慧\n闻所成慧，以名为所缘境，思所成慧，以俱（名义）为所缘境，修所成慧，以义为所缘境", "ke": "明圣道加行"}, "贤圣-6": {"jie": "清净身器的第一因是身心远离，身要远离恶友等染缘，心要远离不善的思惟。\n清净身器的第二因是要喜足少欲\n无喜足和无少欲就是\n对已经得到的想要更多和对没有得到的想要得到", "ke": "广明加行"}, "贤圣-7": {"jie": "喜足少欲能到对治多求和大欲，通有漏无漏。如果是有漏的，就通三界；假定是无漏的，那就通于未至等的九地。\n喜足少欲以无贪为体\n身器清净的第三因是四圣种。四圣种（衣服喜足圣种，饮食喜足圣种，卧具喜足圣种，乐断乐修圣种）也是以无贪为体。\n前三个圣种的自体唯是喜足，第四圣种虽然不是喜足，但因能够弃舍欲贪及有贪，所以也用无贪为性。", "ke": "明身器清净"}, "贤圣-8": {"jie": "前三个圣种是修道的资具，后面一个圣种是助道的事业\n四圣种是为了对治衣服、饮食、卧具和有无有的四种爱\n另外一种解释说，四圣种的目的是为了止息和断除我所欲和我事欲\n前三个圣种让其暂时息下来，第四圣种令其永远断除", "ke": "明身器清净"}, "贤圣-9": {"jie": "入道修行的要门略有二种\n就是不净观和持息念\n贪心重的人和寻心重的人\n如其次第，应分别修不净观和持息念", "ke": "明五停心位"}, "贤圣-10": {"jie": "为了通治显色贪、形色贪、妙触贪和供奉贪四种贪\n从自身骨锁观起，渐渐扩大到以海为边，其间骨锁充满，然后渐渐略观，只观自己全身的骨锁\n这是白骨观的第一阶段——初习业位", "ke": "释不净观"}, "贤圣-11": {"jie": "于自己一具骨锁中，先除去足骨，渐观渐略，直至只观半个头部\n这是白骨观的第二阶段——已熟修位\n由观半个头骨，渐渐略观，最后系心于眉宇间，专注一缘，湛然而住\n这是白骨观的最高阶段——超作意位", "ke": "释不净观"}, "贤圣-12": {"jie": "不净观以无贪为性，通依十地，即四根本静虑及四近分地、中间地和欲界\n缘欲界的色法，在三洲的人中才能修\n所缘是不净相，能缘的不净观与所缘的色法同在一世\n不净观是有漏的，通离染得和加行得", "ke": "诸门分别"}, "贤圣-13": {"jie": "持息念以慧为体，依五地，即欲界、静虑中间、初禅近分、二禅近分和三禅近分。\n以出入息风为所缘境，唯依欲界人（三洲）天趣的有情身才能起修。\n通离染得和加行得，是真实作意，外道没有\n持息念要具六因才得圆满，即数随止观转净", "ke": "别释持息念"}, "贤圣-14": {"jie": "出入息是依身而有的\n同时要依身和心才能转动。\n是有情才有的，属于非执受\n具有等流性，不能被下地的心缘", "ke": "明息差别"}, "贤圣-15": {"jie": "依靠不净观和持息念可以修成止的功夫\n为了修观，应修四念住\n用自相或共相\n观身受心法", "ke": "明四念住"}, "贤圣-16": {"jie": "念住有三种。第一种是自性念住，以闻思修三慧为体。\n剩下的是相杂念住和所缘念住\n四念住的次第是随着身受心法的次第生起的\n因为对治常乐我净四倒所以只有四个念住", "ke": "明别相念住"}, "贤圣-17": {"jie": "修杂缘法念住后\n总观身受心法\n修非常和苦的行相\n还有空和非我的行相", "ke": "明总相念住"}, "贤圣-18": {"jie": "暖善根观四谛\n修十六行相\n暖善根之后生顶善根。和暖一样，顶善根也观四谛修十六行相", "ke": "明善根观行"}, "贤圣-19": {"jie": "暖和顶这两个善根\n都是最初修法念住，后来修四念住\n顶善根之后是忍善根，忍善根只修法念住\n下中品忍和顶一样，观四谛修十六行相", "ke": "明善根观行"}, "贤圣-20": {"jie": "上品忍只观欲界苦谛\n世第一法也是如此，观欲界苦谛一个行相，时间为一刹那\n四善根都是以慧为体，如果并助伴相应法俱有法而言，那五蕴都是全的，助伴中要除去得。", "ke": "明善根观行"}, "贤圣-21": {"jie": "这（四善根）称为顺抉择分\n四善根都是修所成的\n第一种说法，依未至、中间、四根本这六个地能见道；第二种说法，依七个地，除了前面六个，还通欲界。\n依欲界九个地方（人三洲、六欲天）的身可以见道", "ke": "诸门分别"}, "贤圣-22": {"jie": "前三个善根，女的和男的都可以得女善根和男善根两个善根\n第四个善根，女的可以得男女二个善根，男的只能得男善根。\n圣者生到别地，舍原来的善根\n凡夫，命终的时候舍善根", "ke": "诸门分别"}, "贤圣-23": {"jie": "煖顶二善根也可以退舍\n依根本地得四善根，现身决定能够见道\n舍后重得的善根不再是原先的那个善根了\n这两种舍的体性是非得", "ke": "诸门分别"}, "贤圣-24": {"jie": "得了顶善根，就不会断善根了\n得了忍善根，就不会再堕入恶趣\n得了世第一法，就会进入圣道，", "ke": "诸门分别"}, "贤圣-25": {"jie": "煖顶位声闻乘可以转成佛乘，煖顶忍位声闻乘只能转为独觉\n麟角独觉种姓和佛种姓不能转根", "ke": "诸门分别"}, "贤圣-26": {"jie": "今生能够生起顺抉择分，前生必定起过顺解脱分\n修行最快的情况是三生得解脱，第一生起顺解脱分，第二生起顺抉择分，第三生解脱\n顺解脱分，由闻思二慧所成，并以身语意三业为体\n只有在人道的三洲（除北俱卢洲）才能种植顺解脱分善根", "ke": "明得果久近"}, "贤圣-27": {"jie": "世第一法无间隔的\n缘欲界苦谛\n生起无漏的苦法智忍\n苦法智忍之后生起苦法智", "ke": "明十六心"}, "贤圣-28": {"jie": "接着缘其他界（上界）的苦谛\n生起苦类智忍和苦类智\n缘集谛、灭谛、道谛\n也同样生起四种心（法忍、法智、类忍、类智）", "ke": "正明十六心"}, "贤圣-29": {"jie": "这样的十六心\n称为圣谛现观\n现观有三种\n为见现观、缘现观、事现观三种分别", "ke": "正明十六心"}, "贤圣-30": {"jie": "现观十六心都与世第一法\n同依于一地\n忍智按顺序\n为无间道和解脱道", "ke": "明十六心依地"}, "贤圣-31": {"jie": "前十五心属于见道位\n因为全部的四谛理还没有见过的\n现观位圣者称为随信行和随法行\n这是由于根器钝利的差别", "ke": "明见修道别"}, "贤圣-32": {"jie": "具足修惑或者断了修惑一品\n到五品为初果向\n断了此三品修惑（六七八）为二果向\n离了下八地修惑的圣者为三果向", "ke": "依十五心"}, "贤圣-33": {"jie": "到了第十六心\n随着三种向为三种果\n名为信解和见至\n也是由根器钝利来分别", "ke": "依第十六心"}, "贤圣-34": {"jie": "（即便是超越证，）在得果的时候\n还没有得胜果道\n因为没有起胜果道\n所以第十六心是住果位而不是住向位", "ke": "明住果非向"}, "贤圣-35": {"jie": "每一地的烦恼和智慧（能断道）都有九品\n下、中、上这三品中每品再各分下、中、上三品\n到第十六心得预流果，还没有断修所断的烦恼时\n属于住预流果，此时最多在欲界还有七返生死", "ke": "约修无学道"}, "贤圣-36": {"jie": "断欲界修惑三品或四品称为家家，\n断三品时，还余三生叫三家家；断四品时，还余二生叫二家家\n断欲界修惑至第五品时叫做二果向（一来向）\n断欲界修惑第六品时得一来果", "ke": "明一来向果"}, "贤圣-37": {"jie": "断欲界修惑七、八品时叫作一间，还要在欲界受一生\n断欲界修惑七、八品时是三果向（不还向）\n断欲界修惑第九品是得不还果", "ke": "明不还向果"}, "贤圣-38": {"jie": "不还果按在何处般涅槃，可以分为中般、生般、有行般\n还有无行般\n（以及上流般）上流般中如果是杂修静虑的圣者\n能够生色究竟天", "ke": "明果位差别"}, "贤圣-39": {"jie": "无杂修的能生到有顶天\n行无色界的不还有四种（生般、有行般、无形般、上流般）\n在欲界证得涅槃的不还叫现般", "ke": "明七种不还"}, "贤圣-40": {"jie": "行色界的不还又可以分为九种\n中般、生般、上流这三个中，每个又分成三种\n因为业、惑、根的差别\n所以有了三种、九种的差别", "ke": "明九种不还"}, "贤圣-41": {"jie": "安立七善士趣\n因为上流的圣者行相比较类似，所以将九种不还圣者中的上流圣者合为一种\n这七善士只行善不行恶\n都往生上界，不复还来", "ke": "明七善士趣"}, "贤圣-42": {"jie": "经生欲界的圣者\n不会往色无色界投生\n经生欲界的圣者和无色界的圣者\n不需要练根并且不会退", "ke": "明非生上界"}, "贤圣-43": {"jie": "先从第四静虑开始杂修\n一念无漏一念有漏一念无漏时杂修静虑修圆满\n修杂修静虑是为了受生（去五净居天）、现法乐住\n和遮止起烦恼退", "ke": "明杂修静虑"}, "贤圣-44": {"jie": "因为杂修静虑有五品\n所以投生的五净居天也有五种\n得了灭尽定的不还圣者\n他又叫做身证", "ke": "明净居唯五"}, "贤圣-45": {"jie": "上二界的修惑中\n从断第一品\n到有顶第八品\n都名为阿罗汉向", "ke": "明阿罗汉向果"}, "贤圣-46": {"jie": "有顶地第九无间道\n又叫做金刚喻定\n到解脱道时所有的烦恼断尽得到尽智\n成了无学，得到无学果（应果）", "ke": "明向果差别"}, "贤圣-47": {"jie": "有顶地的烦恼要由无漏道断\n其他地的烦恼可以由无漏道和有漏道断\n圣者用有漏道或无漏道断前八地的烦恼\n会得到两个离系得（有漏的离系得、无漏的离系得）", "ke": "因论明治道"}, "贤圣-48": {"jie": "在未至定能起无漏道\n可以离一切地的染\n其余的八个定（中间、近分定、四根本定）能离自地或上地的染\n有漏道只能离挨着的下地的染", "ke": "明道离染通局"}, "贤圣-49": {"jie": "近分定离下地的染\n初、二、三的第九解脱道初、二、三禅的第九解脱道\n可以是根本定也可以是近分定\n四禅以上至有顶地的解脱道只能是根本定", "ke": "明近分道"}, "贤圣-50": {"jie": "用有漏道断烦恼时，无间道是缘下地境，解脱道是缘上地的境\n缘上地的静妙离行相", "ke": "明世道缘行"}, "贤圣-51": {"jie": "不动阿罗汉在尽智之后\n一定会起无生智\n其他五种钝根会起尽智或无学正见\n无学正见是所有的阿罗汉都会生起的", "ke": "明尽智后智"}, "贤圣-52": {"jie": "沙门性是无漏道\n沙门果分为有为果、无为果\n分别是八十九个解脱道及所证得的八十九择灭", "ke": "明道果"}, "贤圣-53": {"jie": "有五个原因安立四果（初、二、三、四）\n①舍之前得的果道和向道，②得到后面更殊胜的果道\n③总集前面所证得择灭，④一时能得到四法智和四类智\n⑤顿修无常等十六行相", "ke": "明立四果因缘"}, "贤圣-54": {"jie": "圣者在用有漏道得二果、三果时，\n①有有漏道和无漏道（见道）所得的择灭杂在一起\n②即使有漏道断，也有无漏道任持（会得无漏离系得），由这两个原因\n所以用有漏道证得二果三果也叫做沙门果", "ke": "别明中二果"}, "贤圣-55": {"jie": "前面所说的沙门性也有其他的异名\n也叫做婆罗门\n也叫做梵轮\n是真梵王（佛）所转", "ke": "明沙门果异名"}, "贤圣-56": {"jie": "沙门性通于三道，然而唯是见道才叫法轮\n称为法轮\n因为见道非常的快速，如同世间的轮一样\n有辐（正见、正思维、正勤、正念），毂（正语、正业、正命），辋（正定）", "ke": "明沙门果异名"}, "贤圣-57": {"jie": "初二三果只能依欲界身证得，四果可以依三界身证得\n因为上二界不能见道\n在色界中乐著禅定不能厌苦，以及经上说“五那含”在欲界见道，上界涅槃的缘故", "ke": "明沙门果依身"}, "贤圣-58": {"jie": "阿罗汉有六种\n退法、思法、护法、安住、堪达、不动\n前五钝根是由有学位的信解种姓所生\n这五种又叫做时解脱", "ke": "明六种姓"}, "贤圣-59": {"jie": "最后一种不动叫做不时解脱\n是从有学位的见至种姓所生\n有的种姓是先有\n有的种姓是后来练根所得", "ke": "明六阿罗汉"}, "贤圣-60": {"jie": "退法、思法、护法、安住、堪达如果在有学位不是相对应的种姓，有可能从果退\n有学、凡夫也有六种种姓\n他们都可以练根，但是在见道的时候不能练根", "ke": "明六姓先后"}, "贤圣-61": {"jie": "退有三种\n已得退、未得退、受用退\n佛只有受用退\n利根阿罗汉有未得退、受用退，钝根阿罗汉有已得退、未得退、受用退", "ke": "明三退"}, "贤圣-62": {"jie": "所有从果上退的圣者\n一定不会命终（在命终前一定会回复果位）\n在住果时所不做的事，退果以后也不做\n因为惭愧心增胜，所以不做", "ke": "明退果时相"}, "贤圣-63": {"jie": "在无学位练根\n因为此钝根性，经久串习，因此各需要九个无间道、解脱道\n而有学位练根各只需一个无间道、解脱道", "ke": "明练根不同"}, "贤圣-64": {"jie": "无学可以依九地练根\n有学只依六地练根\n练根会舍掉之前得到的果道、向道，", "ke": "明练根不同"}, "贤圣-65": {"jie": "无学有九种，七种声闻圣者，缘觉和大觉\n这种差别是因为九种根性的原因\n由于加行、根性、灭尽定", "ke": "明无学九人"}, "贤圣-66": {"jie": "虽然有七种声闻圣者，但是体性只有六种\n（是）见道、修道、无学道各有两种（根器）的原因\n六罗汉中，以无漏智，解脱见修二惑，且兼得灭尽定，以解脱定障的，名为俱解脱", "ke": "明七圣人"}, "贤圣-67": {"jie": "有学称为圆满\n由于根满、果满、定满三个原因\n无学称为圆满", "ke": "明学无学满"}, "贤圣-68": {"jie": "应知一切世出世道，见道修道等\n简略的说只有四种\n分别是加行道、无间道\n解脱道和胜进道", "ke": "诸道差别"}, "贤圣-69": {"jie": "通行共有四种，分别是苦迟、苦速、乐迟和乐速通行\n乐通行依四根本静虑安立\n苦通行依其他定地（无色、中间、未至）安立\n迟速通行是依根器钝利安立", "ke": "明四通行"}, "贤圣-70": {"jie": "菩提分法一共有三十七种\n包括四念住、四正断、四神足、五根、五力、七觉支、八正道支\n菩提名觉，其体是尽智、无生智\n顺趣菩提，故名菩提分", "ke": "明菩提分法"}, "贤圣-71": {"jie": "三十七菩提分法的实体只有十个\n分别是慧、勤、定、信\n念、喜、舍、轻安\n以及戒和寻", "ke": "出体"}, "贤圣-72": {"jie": "四念住、四正断\n以及四神足，此三从力量殊胜的方面\n方便说为慧、勤、定\n实际上所有加行的善法都包含在里面", "ke": "明念住等"}, "贤圣-73": {"jie": "修别相念住、总相念住时念住增；\n顺抉择分，暖位正断增；顶位神足增；忍位五根增；世第一位五力增\n修道位近菩提位，七觉支增\n见道位，速疾而转，通行胜，八正道增。", "ke": "明觉分增"}, "贤圣-74": {"jie": "七觉支和八正道\n一向是无漏的\n其他的四念住、四正断、四神足、五根、五力\n见道以前通有漏，见道后修通无漏", "ke": "明漏无漏"}, "贤圣-75": {"jie": "初静虑，三十七道品全都能修\n未到地定要除去喜\n二静虑要除去寻\n三、四静虑要除去喜和寻", "ke": "明依地"}, "贤圣-76": {"jie": "前三个无色定\n要除去戒（定共戒、道共戒）和喜、寻\n欲界和有顶地\n除了七觉支和八正道，其他的都可以修", "ke": "明依地"}, "贤圣-77": {"jie": "证净共有四种\n分别是佛证净、法证净、僧证净和戒证净\n见苦、集、灭谛的时候得到法证净和戒证净\n见道谛时，兼得佛证净和僧证净", "ke": "明证净"}, "贤圣-78": {"jie": "法证净中的法，苦、集、灭三个谛全都包含在其中\n另外还包含道谛中的菩萨道和独觉道\n佛法僧证净以信为体，戒证净以戒为体\n四个证净都是无漏法", "ke": "明证净"}, "贤圣-79": {"jie": "因为有学位中还有烦恼没有断完\n所以没有解脱支，因此也不立正智支\n解脱有两种，一种是有为，一种是无为\n无学胜解叫有为解脱，一切惑灭叫无为解脱", "ke": "明正智解脱"}, "贤圣-80": {"jie": "其中有为解脱这一无学支\n经中说有两种，分别是心解脱和慧解脱\n正智的体如前““觉”所说\n是尽智和无生智", "ke": "明二支"}, "贤圣-81": {"jie": "初无学心，于未来正生时（无间道时）\n此时从烦恼障中正得解脱，称为正解脱\n道生起在现在位时正在断烦恼，属于正灭位\n道在正灭位时能断烦恼障", "ke": "明解脱时"}, "贤圣-82": {"jie": "断界、离界、灭界，此三界以无为解脱为体\n离界仅是就离贪结而言\n断界是约断其余八结而说\n灭界是指灭贪等结的所隋增事，即从灭烦恼的所缘境来讲", "ke": "明灭断离"}, "贤圣-83": {"jie": "缘苦集的忍智称为苦集慧，此慧称为厌，能厌苦集\n缘四谛境，能断惑得道都称为离，能够离烦恼\n厌和离有广狭的相对关系\n所以应该分有厌非离、有离非厌、有厌亦离、非厌非离四句来讨论。", "ke": "明厌离通局"}, "智-1": {"jie": "无漏慧中的忍不是智\n尽智、无生智是智，但不可名为见\n其余的无漏诸慧，一一皆通智、见二性，但不可以名之为忍。\n有漏慧皆是属于智性所摄，其中有六个同时属于见性所摄。", "ke": "明忍智见别"}, "智-2": {"jie": "十智总的来说可以分类两类，即有漏智和无漏智\n有漏智，亦可称为世俗智\n无漏智，复分为法智与类智的两种差别。", "ke": "明十智相殊 · 明渐增至十 · 明二智三智"}, "智-3": {"jie": "世俗智，遍以一切有为无为诸法，为所缘的境界。", "ke": "明十智相殊 · 明渐增至十 · 明二智三智"}, "智-4": {"jie": "法智、类智，由缘四谛境，是有差别的，所以分为苦、集、灭、道的四智\n法、类及四谛的六智，到了无学身上，假使不是见性的，就又名为尽智、无生智了\n尽无生智初起时，唯以苦、集、类的三智为性", "ke": "明十智相殊 · 明渐增至十 · 明三增至九"}, "智-5": {"jie": "于前面所说的九种智中，有法智、类智、道智以及世俗智的四智，可以成为他心智\n于胜地不知，于胜根不知，于胜位不知\n他心智，唯以现在他身的心心所为缘境，不能知过去、未来的他心", "ke": "明十智相殊 · 明渐增至十 · 明九增至十"}, "智-6": {"jie": "为法智品所摄的他心智，不能了知类品心，为类智品所摄的他心智，不能了知法品心", "ke": "明十智相殊 · 明渐增至十 · 明九增至十"}, "智-7": {"jie": "智是能知，四圣谛为所知，能知知于所知\n罗汉圣者，于无学位中，若正自知，我已知苦，我已断集，我已证灭，我已修道，有此尽行相智，名为尽智。罗汉圣者，于无学位中，若正自知，我已知苦，没有更可知的，我已断集，没有更可断的，我已证灭，没有更可证的，我巳修道，没有更可修的。由此无生行相所有的智慧，名无生智。", "ke": "明十智相殊 · 明尽无生别 · 明九增至十"}, "智-8": {"jie": "由自性的因缘，立世俗智。由对治的因缘，立法与类的二智。\n由行相的因缘，立苦与集的二智。由行相与境的因缘，立灭与道的二智。\n由加行的因缘，立他心智。由事办的因缘，建立尽智。由因圆的因缘，立无生智。\n由上面所说的七种因缘，建立如此十智的差别。", "ke": "明十智相殊 · 明建立十智 · 明九增至十"}, "智-9": {"jie": "彼缘于灭道的法智，在修道位的当中，兼能对治上界的修所断惑。\n类智必无能治欲界", "ke": "明十智相殊 · 明法类智兼治 · 明九增至十"}, "智-10": {"jie": "法智缘欲界的四谛，作非常、苦、空、非我等的十六行相；类智缘上界的四谛，亦作非常、苦、空、非我等的十六行相，所以各各俱有十六行相。\n十智中的世俗智，因为是缘一切法的，不但作此十六行相，而且更有所余自相共相之行。\n十智中的苦等四智，各对自谛作四种的行相", "ke": "明十智相殊 · 明渐增至十 · 明二智三智"}, "智-11": {"jie": "无漏的他心智，属于道谛所摄，所以就缘道谛，而唯作道、如、行、出的四行相\n有漏的他心智，唯缘自所缘的心心所的自相\n他心智，不论是有漏的，还是无漏的，都是唯缘一事，即缘心时不缘心所，缘心所时则不缘心", "ke": "明十智行相 · 明十智行相 · 明九增至十"}, "智-12": {"jie": "十智中的尽智、无生智，除去苦谛下的空与非我的二行相，能作其余的十四行相。\n没有无漏行相，可以越此十六行相，因为离这十六行相，所余是不可得的。\n前述有部义，此则叙异说。有余西方师说：有无漏的行相，越此十六行相外，而为所余的行相所摄。", "ke": "明十智行相 · 明十智行相 · 明九增至十"}, "智-13": {"jie": "苦圣谛有四行相，集圣谛有四行相，灭圣谛有四行相，道圣谛有四行相\n假定约他的自体说，那唯是以慧为体，因以慧观四圣谛境，而能作这种种行相的。\n有所缘，是指心心所法，因为心心所法，是有他的所缘境的，即此有所缘法，也就是能行，因能行于所缘境的。一切诸法，皆是所行，因为是为所缘境的", "ke": "明十智行相 · 明实体能所 · 明九增至十"}, "智-14": {"jie": "世俗智通于三性。其余的九智，唯是善性。\n世俗智，通依欲界乃至有顶的九地\n他心智，唯依四根本静虑\n十智中的法智，适以未至、中间、四根本静虑的六地为所依。所余四谛智、类智、尽智、无生智的七智，通依未至、中间、四静虑、下三无色的九地", "ke": "诸门分别 · 明性依地身 · 明九增至十"}, "智-15": {"jie": "十智的现起，共所依身有差别者：假定是他心智，依于欲色界身，都是可以现起的，唯不依于无色界身，因为彼界无有通的。\n法智现起，唯有依于欲界身\n所余的世俗智、类智、四谛智、尽智、无生智的八智，通依三界身而得现起", "ke": "诸门分别 · 明性依地身 · 明九增至十"}, "智-16": {"jie": "诸智与念住相摄的关系\n其中四谛智的灭智，唯摄于最后的法念住中\n十智中的他心智，为四念住中的后三念住所摄，因他心智，能够了知他人受、心、法的三者的\n所余的八智，通为身、受、心、法的四念住所摄。", "ke": "诸门分别 · 明念住摄智 · 明九增至十"}, "智-17": {"jie": "诸智的互相而缘\n其中法、类、道的三智，一一各以九智为所缘境\n十智中的苦智与集智，一一各以二智为所缘境，就是世俗智及有漏所摄的他心智\n十智中的世俗、他心、尽及无生的四智，一一皆以十智为所缘境。灭智不以诸智为所缘境，所以说非", "ke": "诸门分别 · 明十智相缘 · 明九增至十"}, "智-18": {"jie": "谓于一切有为法中分为八种，即三界所系及无漏有为，而此四者各有相应不相应的两种，所以成为八法；其次无为亦有二种，即善性的择灭无为与无记性的虚空、非择灭无为。\n十智中的世俗智，通能缘于上面所列的十法。法智唯能缘于欲界二、无漏道二及善无为的五法。", "ke": "诸门分别 · 明十智缘境 · 正明十智缘境"}, "智-19": {"jie": "类智，唯能缘于色、无色界的相应、不相应二；无漏圣道相应、不相应二，总合成六，再加善无为，就为七法。苦智与集智，各各能缘三界所系的相应、不相应二，三二合为六法，为苦、集智缘\n灭智唯以一善性的择灭无为为所缘境。道智，唯以无漏道的相应、不相应二为所缘境\n他心智，唯以欲界、色界、无漏道的三相应法为所缘境\n十智中的尽智与无生智，各以九法为所缘境，即于十法中，除去无记无为", "ke": "诸门分别 · 明十智缘境 · 正明十智缘境"}, "智-20": {"jie": "以世俗智总缘一切法而为非我行相的时候，那他必然不能缘于自品，所以说除自品。所谓自品，实包含了自体、相应、俱有的三方面。\n这无我观的世俗智体，因为唯是欲色界之所摄的，所以唯是闻思所成慧，不是修所成慧。", "ke": "诸门分别 · 明十智缘境 · 明俗智缘境"}, "智-21": {"jie": "自吾人凡夫，以至三贤四善根的行者，及见道十五心中初起苦法智忍的圣者，如是凡圣，唯成一智，就是世俗智\n人见道至第二念苦法智位的圣者，那就决定成就世俗智、法智、苦智的三智了\n于苦法智后，总有四位：一、第四念的苦类智位；二、第六念的集法智位；三、第十念的灭法智位；四、第十四念的道法智位。于此四位中，各各增一智，所以说一一增", "ke": "诸门分别 · 明人成智 · 明俗智缘境"}, "智-22": {"jie": "于修道未离欲位，即欲界修惑未全断者，亦成七智\n于修道位中，那已离欲的圣者，在成就前所说的七智外，更加他心智之一，总成八智。论说：“如是诸位，若已离欲，各各增一，谓他心智”。根据此意，可说从异生、圣见道初念位，乃至修道位，一一可增一他心智，不可唯约最后位增一为八。\n于无学道中，假定是钝根时解脱的圣者，那他决定成就九智，即于十智中，除去无生智之一；假定是利根不时解脱的圣者，那他决定十智完全成就。", "ke": "诸门分别 · 明人成智 · 明俗智缘境"}, "智-23": {"jie": "于见道位中的八忍七智，不管是忍起还是智起，都即彼忍智于未来修的，而且唯修同类不杂余修\n于见道位中，苦、集、灭的三类智，正现起的时候，能兼修未来现观边的世俗智", "ke": "诸门分别 · 约位辨修 · 约见道辨"}, "智-24": {"jie": "不生，是说此世俗智，不论是在观中或出观后，都不得现起。不论依于那一地见道现前，都能修未来的自地下地，即修此世俗智，从未至、中间、四静虑、欲界的七地为所依。\n世俗智，假定是在苦、集边修，那就适为四念住摄，因苦、集二谛是通于身、受、心、法四境的；假定是在灭谛边修，那就唯属最后法念住摄，因灭唯是属于法境的\n依于那一谛修，就以那一谛的行相，缘此谛为境\n此智是由加行得，而不是由生得的", "ke": "诸门分别 · 约位辨修 · 约见道辨"}, "智-25": {"jie": "谓断欲界、初定、二定、三定、四定、空无边处、识无边处、无所有处八地中惑而有的无间道\n尚有欲圣者所有的加行、解脱、胜进诸道", "ke": "诸门分别 · 约位辨修 · 约见道辨"}, "智-26": {"jie": "断有顶地的八解脱道，即于九解脱道中，除去第九一解脱道\n八无间道及有欲余道所修的未来七智，就是法、类、苦、集、灭、道、世俗的七智；有顶八解脱道所修的未来七智，就是于上七智中，除一世俗智，加一他心智。\n此上九无间道，于未来能修法、类、苦、集、灭、道的六智。断欲界的第九解脱道、第九胜进道、断上七地的诸解脱道及诸胜进道、断上八地的诸加行道、断有顶前八品惑的诸胜进道：如是一切，皆名余道。此诸余道，于未来能修八智，即于前六智上，更加世俗智及他七智，总成八智", "ke": "诸门分别 · 约位辨修 · 约见道辨"}, "智-27": {"jie": "假定是钝根的时解脱阿罗汉，要除去无生智，唯修九智；假定是利根的不时解脱阿罗汉，那就具修十智了。\n于无学位，诸胜进道，也有修九修十的差别，至于其道理，如前所说是一样的，所以说亦然", "ke": "诸门分别 · 约位辨修 · 约见道辨"}, "智-28": {"jie": "假定是在有学位上练根所有的诸无间道，那他能修未来苦、集、灭、道、法、类的六智。假定是在无学位上练根所有的诸无间道，那他能修未来的七智，即于前六智上，更加一尽智。\n有学位上练根所有的诸解脱道，假定是还没有离欲的，那他能修未来苦、集、灭、道、法、类的六智。假定是已离欲的，那他就能修未来的七智，即于前六智，更加一他心智。有学位上练根所有的加行道，假定是还没有离欲的，那他能修未来的苦、集、灭、道、法、类、世俗的七智。假定是已离欲的，那他能修未来的八智，即于前七智上，更加一他心智。有学位上练根所有的诸胜进道，此所修的七智、八智，都如前加行说\n无学位上的退法等五的种性，在修练根的时候，如果还在前八品解脱道的阶段上，那他能修未来苦、集、灭、道、法、类、他心、尽的八智。退法等前四种性，在修练根的时候，如果到达第九品解脱道的阶段上，那他就能修未来的九智，即于前八智上，更加一世俗智。第五堪达种性，在修练根的时候，如果到达第九品解脱道的阶段上，那他能修未来的十智。无学位上练根所有的诸加行道，除无生智外，那他能修未来其余的九智。无学位上练根所有的诸胜进道，假定足钝根性的，除无生智外，那他能修未来其余的九智；假定是利根性的，那他能修未来的十智，所以说一切。", "ke": "诸门分别 · 约位辨修 · 约余位辨"}, "智-29": {"jie": "杂修无间道及修五通的诸无间道，有学圣者能修未来苦、集、灭、道、法、类、世俗的七智；无学圣者钝根性者，能修未来的八智，即于十智中，除去他心智及无生智。利根性者，能修未来的九智，即于十智中，除去他心智。\n余道，是指杂修及修五通的诸解脱道、加行道、胜进道。有学位能修未来的八智，即于十智中，除去最后的尽及无生的二智。无学应果位上杂修这些余道，钝根性者，能修未来的九智，即于十智中，除去最后的无生智。利根性者，能修未来的十智。", "ke": "诸门分别 · 约位辨修 · 约余位辨"}, "智-30": {"jie": "要知圣者所起的诸余功德以及异生诸位，所修智的多少，皆如道理所说，应该好好的思量。圣者生起诸余四静虑、四无量等修所成摄的有漏功德时，假定他是一个有学而尚未离欲的圣者，那他能修未来的七智，即于十智中，除去他心、尽及无生的三智；假定他是一个有学而已离欲的圣者，那他能修未来的八智，加一他心智。无学而属钝根性，那他能修未来的九智，即于十智中，除一无生智；属利根性的，那他能修未来的十智。异生位上，假定是未离欲的，那他唯能修未来世俗的一智，余者皆不得修，假定是已离欲的，那他就能修未来的二智，谓于世俗智外，再加一他心智。", "ke": "诸门分别 · 约位辨修 · 约余位辨"}, "智-31": {"jie": "诸道，是指世俗道及无漏道。假定是修有漏法，总有两类：一、诸道依此地现起之时，能修未来的此地有漏。二、诸道得此地初所得法时，能修未来的此地有漏。\n一、为离此地时，能修未来此地无漏及下地无漏。唯此所谓修此地下地，是望离染地说，不是望依地说。二、得此地时，能修未来此地无漏及下地无漏。三、依此地中诸道现起时，能修未来此地无漏及下地无漏。", "ke": "诸门分别 · 约位辨修 · 约依地辨"}, "智-32": {"jie": "唯初尽智现在前的时候，其力足能遍修九地有漏而为意地所摄的闻、思、修所成的不净观等无量胜功德\n然而此若生于上地，那他必不修下地善。\n先时从来所未曾得过，而现在开始得了，当知此得是由用功所得的，听以名为所修，假使先时曾经得过的，后因某种因缘又弃舍了，现在纵然还得前所舍的，但不得名为所修", "ke": "诸门分别 · 约位辨修 · 约依地辨"}, "智-33": {"jie": "得习二修。如此二修，是依有为善法而建立的。于未来世唯有一个得修，因能起得而得的；于现在世则具得习二修，有法俱得，名为得修，体现行故，名为习修\n治遣二修。如此二修，是依诸有漏法而建立的。光记说：“此有漏法，望对治道生边，有能治故，名对治修”。遣修，就是除遣修，谓望离缚义边，除遣惑缚，名除遣修。", "ke": "诸门分别 · 约位辨修 · 明四修义"}, "智-34": {"jie": "谓佛果位上的十力、四无畏、三念住、大悲，如是总合名为十八不共法\n处非处智力，以十智为体。处谓合道理义也。如说善因能感爱果，造不善业能招恶果，斯有是处。非处谓不合道理义也。\n业异熟智力，以八智为体，除灭道二智也。知如是类业，感如是异熟", "ke": "明不共法 · 举数标名 · 明四修义"}, "智-35": {"jie": "定谓第三，静虑、解脱、等持、等至智力。根，谓第四，根上下智力，能知众生信等五根，有上下故。解谓第五，种种胜解智力 ，能知众生种种喜乐殊，胜解故。界谓第六，种种界智力，能知众生种种性故。此之四力，九智为体，唯除灭智\n遍趣行智力，一切诸行，皆能趣果，佛智能知。若谓但缘能趣为境，九智为体，除灭智也。若谓亦缘所趣为境，十智为体。\n宿住随念智力，能知过去宿住事故；宿住死生智力，能知众生死此生彼故。此二智力，缘事法故，俗智为体\n漏尽智力。言漏尽者，谓涅槃择灭也。若谓但缘漏尽为境，名漏尽智力，以六智为体，除苦、集、道、他心四智，以此四智不缘灭故。若漏尽身中，所得智故，名漏尽智力，以十智为体", "ke": "明不共法 · 依名别释 · 明十力 · 明佛心力"}, "智-36": {"jie": "宿住、死生二力，依四静虑起。所余八智，通依十一地起，谓欲界、四禅、未至、中间，并四无色\n此之十力，依赡部洲男子佛身\n智于境中，知无碍故，名之为力", "ke": "明不共法 · 依名别释 · 明十力 · 明佛心力"}, "智-37": {"jie": "佛的身跟那罗延神那么大的力量\n佛身支节，一一皆具那罗延力\n那罗延力量，象等七力，十十倍增\n如是身力，以触为体。谓所触中，属于四大种的差异", "ke": "明不共法 · 依名别释 · 明十力 · 明佛身力"}, "智-38": {"jie": "一、正等觉无畏，十智为体，犹如初力；二、漏永尽无畏，或六智、或十智为体，如第十力；三、说障法无畏，八智为体，如第二力；四、说出苦道无畏，或九智、或十智为体，如第七力\n三念住者，以念慧为体。一、缘顺境不生欢喜念住，第二、缘违境不生忧戚念住，第三、缘顺违境不生欢戚念住", "ke": "明不共法 · 依名别释 · 明四无畏 · 明佛身力"}, "智-39": {"jie": "如来大悲，俗智为体，以缘一切有情事境界故\n由五义故。一、资粮大，谓大福德智慧资粮所成办故。二、行相大，谓此力能于三苦境作行相故。三、所缘大释颂“境“字，谓是总以三界有情为所缘故。四、平等大，谓普利乐诸有情故。五、上品大，更无余悲能齐此故。\n此与悲异，由八种因：一、由自性异，二、由行相异，三、由所缘异，四、由依地异，五、由依身异，六、由证得异，七、由救济异，八、由哀愍异", "ke": "明不共法 · 依名别释 · 明大悲 · 明佛身力"}, "智-40": {"jie": "佛三等，一、由资粮等圆满故，二、由法身等成办故，三、由利他等究竟故", "ke": "明不共法 · 依名别释 · 明佛同异 · 明佛身力"}, "智-41": {"jie": "还有其它的佛法，这个功德，跟圣者（就是其他的声闻缘觉）共，乃至异生也有的\n谓无诤、愿智、四无碍解，此三二乘亦有。五通、静虑、四无色、八等至、三等持、四无量、八解脱、十遍处等，异生亦有。", "ke": "明共功德 · 总标名 · 明佛同异 · 明佛身力"}, "智-42": {"jie": "无诤行以世俗智为体，\n依第四禅发，乐通行中，此最胜故。言不动者，六无学中，唯不动性，有无诤智\n唯人三洲，有无诤智。缘未生者，缘未来惑，令不起故\n欲界的烦恼，缘未生迷事烦恼，就是修所断的烦恼。", "ke": "明共功德 · 别解释 · 明共圣德 · 明无诤行"}, "智-43": {"jie": "以愿为先，引妙智起，如愿而了，故名愿智。遍缘一切法。\n无碍解有四种，法无碍解、义无碍解、词无碍解、辩无碍解", "ke": "明共功德 · 别解释 · 明共圣德 · 明愿智"}, "智-44": {"jie": "所缘的一个是名，一个是义，一个是言，一个是说道\n无退智，不会退的智慧为它的体\n法无碍解、词无碍解，只有世俗智\n法无碍解依五地，词无碍解依二地", "ke": "明共功德 · 别解释 · 明共圣德 · 明无碍解"}, "智-45": {"jie": "义无碍解可以十个智，或者是六个智。辩无碍解，九个智，就是除灭智\n从欲界到有顶都能起这个无碍解\n得了一个，必定四个都具足\n其余的跟无诤一样", "ke": "明共功德 · 别解释 · 明共圣德 · 明愿智"}, "智-46": {"jie": "无诤、愿智、四无碍解，此六皆依边际定得\n边际定，体有六种，谓四无碍、无诤、愿智，此六除词，更加延促寿等边际，故体成六，谓无诤边际，乃至延促等边际。边际唯依第四禅\n有遍顺的意思，到究竟的意思，叫边际定\n佛是离染得，其余圣者加行得", "ke": "明共功德 · 别解释 · 明共圣德 · 明依边际定力得"}, "智-47": {"jie": "通是六种，神境通，天眼通，天耳通，他心通，宿住通，漏尽通，成了六个\n此六神通，解脱道摄，慧为其体", "ke": "明共功德 · 别解释 · 明共凡德 · 明六通"}, "智-48": {"jie": "神境、天眼、天耳、宿住，此之四通，俗智为体，他心智通，五智为体，谓法、类、道、世俗、他心\n漏尽智通，如漏尽力，或六智，或十智为体\n前之五通，依四静虑\n五通唯缘自下地境。如神境通，于初禅发，能于初禅及下欲界，行化自在，于上不然，势力劣故。余四通亦尔", "ke": "明共功德 · 别解释 · 明共凡德 · 明六通"}, "智-49": {"jie": "诸大声闻，能于二千世界，起神通用，麟觉能于三千世界，佛能于无数世界，神通自在", "ke": "明十智相殊 · 明渐增至十 · 明九增至十"}, "智-50": {"jie": "初之三通，唯身念住，缘色起故。他心智通，唯三念住，不知色故，无身念住。所余宿住及漏尽通，四念住摄，谓缘五蕴一切法故。\n天眼、耳二通，无记性摄，以二通体，是眼耳识相应慧故\n除天眼、耳，所余四通，性皆是善", "ke": "明共功德 · 别解释 · 明共凡德 · 明六通"}, "智-51": {"jie": "第五宿住通，是第一宿住智证明；第二天眼通，是第二死生智证明；第六漏尽通，是第三漏尽智证明\n于六通中，唯三名明，谓能对治三际愚故：宿住智明，治前际愚；死生智明，治后际愚；漏尽智明，治中际愚\n此三明中，后漏尽明，容有是真，通无漏故。前二名明，但是假说，以有漏故\n有学身中，虽有宿住及死生智，不名明者，以彼身中有暗惑故", "ke": "明共功德 · 别解释 · 明共凡德 · 辨三明"}, "智-52": {"jie": "第一神境通，名第一神变示导；第四他心通，名第二记心示导；第六漏尽通，名第三教诫示导\n三示导中，教诫示导，最为尊胜\n教诫示导，定由第六漏尽通成，故最为尊\n教诫示导，以能如实方便说法，故能令他引当利益果（人天果）及安乐果（涅槃果）", "ke": "明共功德 · 别解释 · 明共凡德 · 明三示导"}, "智-53": {"jie": "有这个殊胜的神变作用，所以神就叫等持。等持是体，神是用\n神变名境，境有二种：一行，二化\n行有三种：一者运身，谓乘空行，犹如飞鸟；二者胜解，谓极远方作近思惟，便能速至；三者意势，谓极远方，举心即至，此势如意，得意势名。意势唯佛，运身、胜解，亦通二乘", "ke": "明共功德 · 别解释 · 明共凡德 · 别明神境"}, "智-54": {"jie": "化有二种：一、欲界化，二、色界化。欲界化四，谓四外处，色、香、味、触，名欲界化。色界化二，所谓色、触，名色界化，以色界中无香、味故\n此二界化，各有二种：一、似自身化，二、似他身化", "ke": "明共功德 · 别解释 · 明共凡德 · 别明神境"}, "智-55": {"jie": "从神境通，生变化心，总有十四，谓初定果有二，二定果有三，三定果有四，第四定果有五\n如得初禅定，必得初禅化，乃至得第四禅定，必得第四定化，以果化心，与所依定，俱时得故\n净者善静虑也，自者化心也。此能化心：一、从净生，二、从自生。又此化心，能生二心，谓生净心，及生化心", "ke": "明共功德 · 别解释 · 明共凡德 · 别明神境"}, "智-56": {"jie": "化前境事，由自地心。如化四境是欲化心，化初禅境，是初禅化心\n化所发语，通自、下心。谓欲、初禅化所发言，此言必是自地心起，依二禅等化所发言，此必依下地心发\n若一化主，起多化身，要化主语时，诸所化方语，言音诠表，一切皆同。佛则不尔，与所化语，容不俱时，言音所诠，亦容有别", "ke": "明共功德 · 别解释 · 明共凡德 · 别明神境"}, "智-57": {"jie": "先愿力，留所化身，后起余心，发语表业\n有说愿力，留所化身，亦得死后。如大迦叶留骨锁身至慈尊世，唯坚实体，可得久留，即骨锁身\n有余师说，无有留身得至死后。迦叶留者，天神扶持，非愿力", "ke": "明共功德 · 别解释 · 明共凡德 · 别明神境"}, "智-58": {"jie": "初起化事，由多化心，方能化作一所化事；后若成满，与此相违，但一化心，即能化作众多化事\n此前十四，能变化化心，从定修生，无记性摄，四无记中，通果无记\n余生得等，能变化心，即通三性", "ke": "明共功德 · 别解释 · 明共凡德 · 别明神境"}, "智-59": {"jie": "眼、耳通，依四静虑所生，净色眼、耳二根，见色闻声，名天眼耳\n唯有修得天眼耳根，恒是同分，又无缺坏，能取被障，极细远等，诸方色声", "ke": "明共功德 · 别解释 · 明共凡德 · 别释眼耳"}, "智-60": {"jie": "神境通类，总有五种：一者修得，二者生得，三者呪得，四者药得，五者业得\n他心智通，类有四种：一者修得，二者生得，三者呪得，四者占相", "ke": "明共功德 · 别解释 · 明共凡德 · 明通种类"}, "智-61": {"jie": "所余天眼、天耳、宿住三通，唯有三种，谓修、生、业\n此五通中，神境等三，若修得者，唯是善性，天眼天耳，是无记性。除修得外，余生得等，皆通三性\n人中都无生得通者，余皆容有\n于地狱趣，初受生时，有生得他心智，及宿住智，知过去等，苦受逼已，更无所知", "ke": "明共功德 · 别解释 · 明共凡德 · 明通种类"}, "定-1": {"jie": "四静虑各有二种：生静虑，定静虑。生为果，定为因，生静虑，是依定静虑而生的色界诸天的果报。在世间品中已说。\n定静虑（如身在欲界，而其断惑发得之色界之定，名定静虑），为生静虑之因的修得定。此定体唯善性，心一境性。以善等持为体，若加助伴，则以五蕴为体 。", "ke": "明四静虑"}, "定-2": {"jie": "静虑体虽同为心一境性，然因有具支数不同，故分为四静虑。如俱伺喜乐支名初静虑，后三定逐渐离前支。\n四无色各有二种：生无色，定无色。生无色体，即四无色天。无色定，同为心一境性，体相无别，而分为四种。是均离下地之染有别之故。", "ke": "明四静虑"}, "定-3": {"jie": "四根本无色并上三无色近分，总名为除色想。空无边处近分，不能名为除色想，是因为它缘下界地色，还有色想存在，故不能名。\n无色界之所以说为无色，是因为悉皆没有色之缘故。问：无色界多劫，色相续断后没生下，色从何生呢？答：后色从心生起。即过去生中所起的色异熟因熏习在心，功能令熟，是故今色从彼心生。（论主依经部释）", "ke": "明四无色定"}, "定-4": {"jie": "空无边处等前三无色，是从加行而安立的。\n有顶地，无下地明慧胜想，故名非想；有昧劣之想，故名非非想。此从当体立名。", "ke": "明四无色定"}, "定-5": {"jie": "以上四静虑，四无色定，合而为八等至。前七个各有\n味、净、无漏等至，最后非想非非想地，有味、净二等至。此地想昧劣故，无漏不起。", "ke": "总明八等至"}, "定-6": {"jie": "味等至，是与贪等烦恼相应，而味著于境之定。净等至，是与无贪等清净法相应而起有漏世善之定。", "ke": "总明八等至"}, "定-7": {"jie": "初静虑具有五支：寻、何、喜、乐、等持。\n第二静虑唯具四支：内等净、喜、乐、等持。", "ke": "明静虑支数"}, "定-8": {"jie": "第三静虑具有五支：行舍、正念、正慧、乐受、等持。\n第四静虑唯具四支：行舍、念清净、舍受、等持。", "ke": "明静虑支数"}, "定-9": {"jie": "实际上的体只有十一个。初禅、二禅的乐，喜乐的乐是属于轻安的乐，不是身受乐，因为定中没有身受。\n第二禅的内等净就是信根，所谓喜，就是喜受。", "ke": "明支体"}, "定-10": {"jie": "初禅染中，没有离生喜乐。非离烦恼而得生故。第二染中。无内等净，烦恼浊故。\n第三染中，无正念、正慧，染乐乱故。第四染中，无舍念清净。烦恼染故。余师说，初二染中，但无轻安，后二染中，唯无行舍，以此二种大善地法摄故，染定无。", "ke": "明染无支"}, "定-11": {"jie": "前三静虑名为有动地，有水火风等灾患。第四静虑无八灾患动，是故世尊说名不动。\n八灾患是：寻、伺、苦、乐、忧、喜、入息、出息。有余师说，第四静虑如密室灯，照而无动故名不动。", "ke": "明不动"}, "定-12": {"jie": "生静虑从初静虑开始，挨了次第，第一个初静虑有喜乐舍受，第二个静虑有喜舍二受，第三禅静虑有乐舍二受，第四静虑只有舍受。", "ke": "明生受有异"}, "定-13": {"jie": "问：上三静虑，既没有眼耳身三识身。又没有寻伺二心所。生彼静虑中，怎么能有见闻触以及生起表业？\n生到上面三个静虑也可以起眼识、耳识、身识，也可以起发表的心，当地他们没有的，但是，可以借初静虑的拿来用。这个心无覆无记的，这是通果心，无覆无记的，或者威仪路。\n三性分别，此五趣体，不通善染性，唯无覆无记，过去业所招，是异熟生无记，五趣唯是有情数摄，体非中有", "ke": "明五趣"}, "定-14": {"jie": "第一个先决条件全不得，一点也没有得到的，善的有漏定，下面的地的染污离掉了，得上地的净定。\n无漏定，决定是离染得，离开了那个染污，用无漏道断掉了，得到无漏定等至。染污定，“生”，生到那个地方去，从上地死掉了，投生到这个地方，起它的染污定；“退”，本来是离了染，现在染污又起来了，也能生染污定。", "ke": "初明得等至"}, "定-15": {"jie": "无漏等至无间生自地、上地、下地的净无漏二种等至。然于上下地各各只能至第三，不能超生第四，因远力不够故。所以于无漏四静虑，三无色的七等至中，从初静虑无间生六乃至无所有无间生七。\n净等至无间生，如无漏等至一样，且瘐生自地染等至。故有顶净，无间生六乃至初静虑净无间生七。", "ke": "明等至相生"}, "定-16": {"jie": "味等至无间能生自地净。味二种等至，并能生次下一地净等至。\n死时生得净定，一一能生三界九地染定；死时生得染定。一一能生自地及下地染定。但不生上染，未离下染。不生上故。", "ke": "明等至相生"}, "定-17": {"jie": "明净等至有四种。三等至中之净等至，复有四种之别。即顺退分定，顺住分定，顺胜进分定，顺抉择分定 。其中七地各四，有顶地唯三，无顺胜进分，以此处无上地可趣故。", "ke": "明顺四分定"}, "定-18": {"jie": "这个四个分，按了次第，顺退分是顺烦恼的，会退的；顺住分，就是顺自地的，自己本来那个地，能安住的；顺胜进分，可以往上进去，顺上的；那么顺决择分，顺了无漏的，可以通到无漏的。\n这四个分，互相来对待的看，能够生出二个三个三个一个。", "ke": "明顺四分定"}, "定-19": {"jie": "问：如上所说，净、无漏等至，皆能上下超至第三。但行者修超等至时，究竟是怎样修法呢？到了加行成满时，差别又是怎样的呢？列二类六品。二类定，指本善等至分为有漏无漏两种。\n观行者修超定时，先于有漏八等至。顺逆均次，现前数习。次于无漏七等至顺逆均次。现前数习。又次于有漏无漏等至顺逆间次，现前数习。又次于有漏顺逆均超，现前数习。又次于无漏顺逆均超，现前数习，是名修习超加行成满。后于有漏无漏。能修超等至的人，唯三洲中的利根不时解脱罗汉。", "ke": "明修超等至"}, "定-20": {"jie": "诸等至的生起，是依自地身及下地身。不依上地身起。以无用故\n唯有生于有顶地的圣者起无所有处的无漏等至。为了彻底断尽有顶地的诸余烦恼。因为有顶自地本身无圣道。所以于下圣道欣乐而起。", "ke": "明等至依身"}, "定-21": {"jie": "味等至唯缘自地有漏法。色界的净等至和无漏等至。俱能遍缘自、上、下地有为地有为无为境。\n无色界的根本净，无漏等至，不缘下地有漏法。", "ke": "明等至缘境"}, "定-22": {"jie": "问：四禅、四无色的八定，有味、净、无漏三等至。此三中。何者能断惑？答：无漏等至能断惑，净等至的近分亦能断惑。根本净等至和味等至不能断惑。\n1、近分有几种？2、近分与何受相应？3、于味等至三是否悉皆具有？答：近分有八，即色、无色的根本定各有一近分。近分与舍受相应。八近分皆属净等至所摄。", "ke": "明等至断惑"}, "定-23": {"jie": "此中间静虑，无寻唯伺，具三等至，唯舍受相应。这个中间定具足三个等至，味定、净定、无漏定都有。中间静虑通无漏的\n初静虑和未至定是有寻有伺三摩地，中间定是无寻唯伺三摩地，二禅以上是无寻无伺三摩地", "ke": "明中定不同"}, "定-24": {"jie": "空三摩地，它的行相，就是空跟非我的行相。那么“无相”三摩地，灭谛的四个行相，就是灭、静、妙、离\n十六个行相里边，除了空、非我是空三摩地，无相三摩地，灭谛四个行相，其它的还有十个，都属于无愿三摩地。这些四谛的行相相应的，跟它们相应的，就是分了三个三摩地。", "ke": "明单空等三"}, "定-25": {"jie": "以上空三摩地、无相三摩地、无愿三摩地，一一皆通净、无漏二等至，其中唯无漏的三种等持，名三解脱门。因此三种等至，能与解脱涅磐作为通入之门，故名三解脱门。\n这个空空、无相无相、无愿无愿三摩地，这个属于有漏的，但是只有无学，而且是利根的才能修。空空取的是空相。以空的行相来缘前面无学的空三摩地再把它空掉，无愿无愿三摩地，要取非常相。", "ke": "明单空等三"}, "定-26": {"jie": "无相无相是缘无学的无相三摩地，本来无相三摩地是择灭，现在无相无相是缘它的非择灭，但取静相。\n此三重等持，均为厌舍圣道故，唯为有漏定。依欲界、未至、中间、四静虑、四无色的根本等十一地而起。除第二静虑以上之七近分，是因为无胜德之故。所依人唯人趣三洲人，不时解脱罗汉。", "ke": "明单空等三"}, "定-27": {"jie": "现在修诸净及无漏的二善静虑，即能于现前法乐而得寂静安稳。\n依诸定而修天眼通，即能证得殊胜的知见，也就是证得清净眼识相应慧，而领受诸色得以观察。", "ke": "明修四等持"}, "定-28": {"jie": "修三界的诸加行善及无漏善，即得引生分别诸法的性相之慧。\n修金刚喻定，即得诸漏永尽。", "ke": "明修四等持"}, "定-29": {"jie": "四无量心，是将怜愍无量的有情之心，分为慈、悲、喜、舍四种。是对治嗔、害、不欣慰、欲界贪嗔四种障故。\n慈无量心，以无嗔为体，悲无量心，以无嗔或不害为体；喜无量心，以喜受为体；舍无量心，以无贪或无贪无嗔二法为体。", "ke": "明四无量"}, "定-30": {"jie": "此行相次第是，慈的行相是与乐，即愿诸有情得如是乐，如是思惟，入慈等至；悲的行相是拔苦，即愿诸有情离如是苦，如是思惟，入悲等至；\n喜的行相是欣慰，即思惟诸有情离苦得乐是最极快慰之事；舍的行相是有情等，即观有情怨亲平等，舍怨舍亲名舍。四无量心普缘欲界一切有情。上界无嗔等，故不缘。", "ke": "明四无量"}, "定-31": {"jie": "喜无量心唯依初、二静虑二地。余三无量心通依四静虑、未至、中间的六地。有余师说依中间、四禅的五地。第三师说依欲界、未至、四根本、四禅近分的十地。\n四无量心不断惑。原因是：1、四无量心属有漏根本静虑摄。非无漏故。2、是胜解作意相应，而断惑须真实作意。3、遍缘一切有情境故，而断惑须缘法作意。4、断惑是无间道，四无量心属解脱道，能治嗔等四障，是约加行位制伏嗔等说，非实能断惑。此四无量心唯人趣起。初二禅能成四{成一必成四}，第三禅以上成就三无量心，除喜。{成一定成三}", "ke": "明四无量"}, "定-32": {"jie": "解脱有八种,1、内有色想观外色解脱。即于内身有色想之贪，为除此贪，而观外之不净青瘀等色，使贪不起。2、内无色想观外色解脱。即于内身无色想之贪，虽已除了，而想使更坚牢，而观外之不净青瘀等色，使不起贪。3、净解脱身作证具足住。即观净色使贪不起，名为净解脱，观净色的人，证得此净解脱于身中，名身作证，具足圆满得住此定，名具足住。4、空无边处解脱。5、识无边处解脱。6、无所有处解脱。7、非想非非想处解脱。此四解脱，各各能弃舍下地之贪，故名解脱。8、灭受想定解脱身作证具足住。此即灭尽定，是厌受想等心，永住于无心，故名解脱。前三解脱以无贪为体\n于中前二解脱依初、二静虑起，第三解脱依第四静虑起。四无色解脱，以四无色善定为体。", "ke": "明八解脱"}, "定-33": {"jie": "行者入灭尽定，唯从此微微心入，不从想心或微细心入。\n出灭尽定心或起有顶净心，或起下地无所有处的无漏心。{可见，灭定的入心唯有漏，出心通有、无漏。}", "ke": "明八解脱"}, "定-34": {"jie": "前三解脱唯以欲界的可见色为所缘境。所不同的是初、二解脱缘欲界之可憎之色为境，第三解脱缘欲界之可爱之色为境。四无色解脱，各缘自地及上地的苦集灭谛并诸九地类智品道.\n，亦缘自上地苦集谛上的非择灭，并诸九地（无漏：未至、中间、四静虑、三无色）类智品道上非择灭及虚空无为为境。", "ke": "明八解脱"}, "定-35": {"jie": "八胜处：1、内有色想观外色少。2、内有色想观外色多。3、内无色想观外色少。4、内无色想观外色多。5、内无色想观外色青。6、内无色想观外色黄。7、内无色想观外色赤。8、内无色想观外色白。此中前二胜处如前说第一解脱\n次二如第二解脱，后四如第三解脱。也就是说，此八胜处，是从八解脱中的前三解脱开出来的，所以体性、境地等，皆同前三解脱。", "ke": "明八胜处"}, "定-36": {"jie": "十遍处：1、地大遍一切处。2、水大遍一切处。3、火大遍一切处。4、风大遍一切处。5、青色遍一切处。6、黄色遍一切处。7、赤色遍一切处。8、白色遍一切处。9、空无尽遍一切处。10、识无尽遍一切处。此中前八如八解脱中的第三解脱，以无贪为体，依第四静虑，缘可见的假四大和四显色为境。\n后二遍处，如其次第，以空、识二无边处善定为体，各缘自地的四蕴为境。", "ke": "明十遍处"}, "定-37": {"jie": "灭尽定解脱，在前根品已说过，唯有圣者得，凡夫不起，唯加行得，非离染得，而初起时，灭定决定在人中。除灭定外，余解脱等，悉通二得，曾修则离染得，未曾修则加行得。\n四无色解脱，空识二遍处，一一通依三界身起。不过在其初起的时候，大多是依于下地，依自下地皆容后起，唯无所有亦依上地。所余一切皆依欲界人趣身起，由教力故，异生及圣，皆能现起。", "ke": "明得依身"}, "定-38": {"jie": "问：诸有生在色无色界，起静虑无色，由何等别缘？答：由二缘：1、由因力。即前生的顺生业为近修，现前数习的顺现业为数修，此二并为因力，能起四无色定。2、由业力。由顺后业，将起现前势力，能令起无色定。\n生色界天中，起色四静虑，除以上二缘外，另加一法尔力，即器世界将坏时，下地有情自然能起上地静虑。若生欲界，起上定时，于前三缘，更加教力。", "ke": "明起定缘"}, "定-39": {"jie": "以上分别种种法门，皆为宏持世尊教法，何谓正法，当住时？佛的正法有教正法和证正法两种：教正法——三藏十二部，证正法——如来圣智亲证的宇宙万有的实相真理，亦即三乘菩提分法及三乘圣果。\n有受持及正说的人，教正法即能住世；有能依教正修行者，佛的证正法即能久住世间。", "ke": "明正法住世"}, "流通-1": {"jie": "迦湿弥罗毗婆师义和阿毗达磨理都善成立，因此我造俱舍论时多依彼释对法藏，但其中时以经部义宗对婆沙理少有贬量，这是我的过失，判法正理唯在世尊及如来诸大弟子。", "ke": "正明宗旨"}, "流通-2": {"jie": "能为世间作指路人的世尊涅磐日久，众生犹如没有眼目一样，而那些能够依教奉行证果的舍利指等亦随佛灭度了。\n既失大师，又无法将，我们凡夫异生，没有智慧，不见真理，无法自制，起恶寻思，乱惑圣教，其过甚大。", "ke": "伤叹有德"}, "流通-3": {"jie": "无师自悟的佛陀，已入涅槃寂静，能受持如来对教的舍利弗等亦多随如来入灭。\n世间没有依怙，是由于丧失了如来及大弟子等众德之故，由此众生没有正法钩制诸惑象，随意起执，盲目流转。", "ke": "重释有德"}, "流通-4": {"jie": "佛灭度后九百年中，世亲菩萨造论，正法寿命渐次沦亡，如人临终，气至咽喉，须臾即死，于此时中，烦恼增长，诸有智人，应求解脱，勿令放逸。", "ke": "劝学法"}};
